/* Tronc Commun : exercices supplémentaires (séries d’au moins 7 exercices illustrés).
   addExos('id', [...]) ajoute des exercices à la série du chapitre. */
'use strict';
function addExos(id, list) { EXOS[id] = (EXOS[id] || []).concat(list); }
const ball = (x, y, r, c, t) => `<circle cx="${x}" cy="${y}" r="${r}" fill="${c}" stroke="#14213d"/>${t ? `<text x="${x}" y="${y + 4}" text-anchor="middle" fill="#fff" font-weight="bold" font-size="12">${t}</text>` : ''}`;

/* ---------- La gravitation universelle ---------- */
addExos('tc-gravitation', [
  { d: 1, t: 'Poids sur la Terre et sur la Lune', fig: SVG(440, 130, ARW('g4') + ball(90, 70, 50, '#1f6fe0', 'Terre') + ball(330, 80, 26, '#9aa6bf', 'Lune')
      + `<rect x="80" y="2" width="20" height="16" fill="#d98200"/>${VEC(90, 18, 90, 50, '', '#d93a4a', 'g4')}<rect x="320" y="36" width="20" height="16" fill="#d98200"/>${VEC(330, 52, 330, 62, '', '#d93a4a', 'g4')}<text x="160" y="40">g = 9,8 N/kg</text><text x="370" y="40">g = 1,6 N/kg</text>`),
    q: TX`Un astronaute a une masse \(m = 70\ \text{kg}\) avec sa combinaison.<br>1) Calculer son poids sur la Terre (\(g_T = 9{,}8\ \text{N/kg}\)).<br>2) Quelle est sa masse sur la Lune ? Calculer son poids sur la Lune (\(g_L = 1{,}6\ \text{N/kg}\)).<br>3) Combien de fois est-il plus « léger » sur la Lune ?`,
    s: TX`1) \(P_T = m\,g_T = 70\times9{,}8 = 686\ \text{N}\).<br>2) La masse ne change pas : 70 kg. \(P_L = 70\times1{,}6 = 112\ \text{N}\).<br>3) \(\dfrac{P_T}{P_L} = \dfrac{9{,}8}{1{,}6} \approx 6\) : son poids est environ 6 fois plus petit.` },
  { d: 2, t: 'Attraction Soleil – Terre', fig: SVG(460, 110, ARW('g5') + ball(70, 55, 42, '#ffb23e', 'S') + ball(400, 55, 14, '#1f6fe0', 'T') + `<line x1="70" y1="55" x2="400" y2="55" stroke="#9aa6bf" stroke-dasharray="4 4"/>${VEC(112, 55, 168, 55, 'FT/S', '#d93a4a', 'g5')}${VEC(386, 55, 330, 55, 'FS/T', '#d93a4a', 'g5')}<text x="235" y="100" text-anchor="middle">d = 1,5×10¹¹ m (échelle non respectée)</text>`),
    q: TX`Données : \(M_S = 2{,}0\times10^{30}\ \text{kg}\) ; \(M_T = 6{,}0\times10^{24}\ \text{kg}\) ; distance Soleil – Terre \(d = 1{,}5\times10^{8}\ \text{km}\) ; \(G = 6{,}67\times10^{-11}\ \text{N}\cdot\text{m}^2\cdot\text{kg}^{-2}\).<br>1) Calculer l’intensité de la force exercée par le Soleil sur la Terre.<br>2) Donner les caractéristiques de \(\vec F_{T/S}\).<br>3) Avec l’échelle 1 cm ↔ \(10^{22}\ \text{N}\), quelle est la longueur des vecteurs ?<br>4) Donner l’ordre de grandeur de \(d\) en mètres.`,
    s: TX`1) \(F = G\dfrac{M_SM_T}{d^2} = 6{,}67\times10^{-11}\times\dfrac{2{,}0\times10^{30}\times6{,}0\times10^{24}}{(1{,}5\times10^{11})^2} \approx 3{,}6\times10^{22}\ \text{N}\).<br>2) Point d’application : centre du Soleil ; droite d’action : (ST) ; sens : de S vers T ; intensité \(3{,}6\times10^{22}\ \text{N}\).<br>3) 3,6 cm pour chacun des deux vecteurs.<br>4) \(1{,}5\times10^{11}\ \text{m}\) : ordre de grandeur \(10^{11}\ \text{m}\).` },
  { d: 2, t: 'Pesanteur et altitude', fig: SVG(400, 170, ball(140, 120, 70, '#1f6fe0', '') + `<text x="140" y="125" text-anchor="middle" fill="#fff" font-weight="bold">Terre</text><circle cx="140" cy="120" r="100" fill="none" stroke="#9aa6bf" stroke-dasharray="5 4"/><rect x="226" y="62" width="22" height="10" fill="#d98200"/><text x="256" y="66">station (h)</text><line x1="140" y1="120" x2="210" y2="120" stroke="#fff" stroke-width="1.5"/><text x="172" y="114" fill="#fff" font-size="11">R</text>`),
    q: TX`\(g_0 = 9{,}8\ \text{N/kg}\) au sol ; \(R_T = 6400\ \text{km}\).<br>1) Montrer que \(g_h = g_0\dfrac{R_T^2}{(R_T + h)^2}\).<br>2) Calculer \(g\) à l’altitude de la Station spatiale internationale, \(h = 400\ \text{km}\).<br>3) À quelle altitude \(g\) est-elle égale à \(g_0/4\) ?`,
    s: TX`1) \(g_0 = G\dfrac{M_T}{R_T^2}\) et \(g_h = G\dfrac{M_T}{(R_T + h)^2}\) ; en divisant : \(g_h = g_0\dfrac{R_T^2}{(R_T + h)^2}\).<br>2) \(g = 9{,}8\times\Big(\dfrac{6400}{6800}\Big)^2 \approx 8{,}7\ \text{N/kg}\).<br>3) \(\Big(\dfrac{R_T}{R_T + h}\Big)^2 = \dfrac{1}{4} \Rightarrow R_T + h = 2R_T \Rightarrow h = R_T = 6400\ \text{km}\).` },
  { d: 3, t: '« Peser » la Terre', fig: SVG(300, 170, ball(150, 85, 75, '#d98200', '') + ball(150, 85, 45, '#d93a4a', '') + ball(150, 85, 20, '#ffd27a', '') + `<text x="150" y="20" text-anchor="middle" font-size="11">croûte et manteau</text><text x="150" y="90" text-anchor="middle" font-size="11">noyau</text>`),
    q: TX`On mesure au sol \(g_0 = 9{,}8\ \text{N/kg}\). \(R_T = 6{,}4\times10^{6}\ \text{m}\) ; \(G = 6{,}67\times10^{-11}\) SI.<br>1) En exprimant le poids d’un corps de deux façons, établir \(M_T = \dfrac{g_0R_T^2}{G}\) et calculer \(M_T\).<br>2) Calculer la masse volumique moyenne de la Terre (\(V = \tfrac{4}{3}\pi R^3\)).<br>3) Les roches de surface ont \(\rho \approx 2{,}7\times10^{3}\ \text{kg/m}^3\). Que peut-on dire du centre de la Terre ?`,
    s: TX`1) \(mg_0 = G\dfrac{M_Tm}{R_T^2} \Rightarrow M_T = \dfrac{g_0R_T^2}{G} = \dfrac{9{,}8\times(6{,}4\times10^{6})^2}{6{,}67\times10^{-11}} \approx 6{,}0\times10^{24}\ \text{kg}\).<br>2) \(V = \tfrac{4}{3}\pi(6{,}4\times10^{6})^3 \approx 1{,}1\times10^{21}\ \text{m}^3\) ; \(\rho = \dfrac{M_T}{V} \approx 5{,}5\times10^{3}\ \text{kg/m}^3\).<br>3) La moyenne est deux fois plus grande que celle des roches de surface : le centre (le noyau, riche en fer) est beaucoup plus dense.` },
]);

/* ---------- Exemples d’actions mécaniques ---------- */
addExos('tc-actions', [
  { d: 1, t: 'Classer des actions mécaniques', fig: SVG(460, 120, `<line x1="20" y1="10" x2="120" y2="10" stroke="#5b6577" stroke-width="4"/><line x1="70" y1="10" x2="70" y2="50" stroke="#5b6577" stroke-width="2"/><circle cx="70" cy="66" r="16" fill="#ffd27a" stroke="#14213d"/><text x="70" y="110" text-anchor="middle">(1) lampe</text>
      <rect x="170" y="40" width="40" height="40" fill="#d93a4a"/><rect x="210" y="40" width="40" height="40" fill="#1f6fe0"/><circle cx="290" cy="60" r="6" fill="#5b6577"/><text x="230" y="110" text-anchor="middle">(2) aimant et bille</text>
      <path d="M380 90 L380 20 L440 80 Z" fill="#eaf1fd" stroke="#14213d"/><line x1="350" y1="95" x2="450" y2="95" stroke="#14213d" stroke-width="3"/><text x="400" y="114" text-anchor="middle">(3) voilier</text>`),
    q: TX`Pour chaque situation, classer l’action indiquée : de contact ou à distance ; localisée ou répartie.<br>a) (1) l’action du fil sur la lampe ; b) (1) l’action de la Terre sur la lampe ; c) (2) l’action de l’aimant sur la bille d’acier ; d) (3) l’action du vent sur la voile ; e) l’action de l’eau sur la coque du voilier.`,
    s: TX`a) Contact, localisée (point d’attache). b) À distance, répartie (dans tout le volume). c) À distance, répartie. d) Contact, répartie (sur la surface de la voile). e) Contact, répartie (sur la surface immergée).` },
  { d: 2, t: 'Pression des pneus d’une voiture', fig: SVG(440, 130, `<rect x="60" y="30" width="300" height="50" rx="14" fill="#1f6fe0"/><rect x="120" y="5" width="170" height="35" rx="10" fill="#6aa5ff"/>${ball(120, 88, 22, '#14213d', '')}${ball(300, 88, 22, '#14213d', '')}<line x1="20" y1="110" x2="420" y2="110" stroke="#5b6577" stroke-width="2"/><rect x="104" y="108" width="32" height="5" fill="#d93a4a"/><rect x="284" y="108" width="32" height="5" fill="#d93a4a"/><text x="220" y="128" text-anchor="middle" font-size="11">surface de contact d’un pneu : 150 cm²</text>`),
    q: TX`Une voiture de masse \(m = 1200\ \text{kg}\) repose sur ses 4 pneus. Chaque pneu touche le sol sur \(S = 150\ \text{cm}^2\). \(g = 10\ \text{N/kg}\).<br>1) Calculer le poids de la voiture.<br>2) Calculer la pression exercée par la voiture sur le sol, en Pa puis en bar.<br>3) Si les pneus sont dégonflés, la surface de contact augmente. Que devient la pression ?`,
    s: TX`1) \(P = mg = 12\,000\ \text{N}\).<br>2) \(S_{tot} = 4\times150\times10^{-4} = 6{,}0\times10^{-2}\ \text{m}^2\) ; \(p = \dfrac{F}{S} = \dfrac{12\,000}{0{,}06} = 2{,}0\times10^{5}\ \text{Pa} = 2{,}0\ \text{bar}\).<br>3) Pour la même force, une surface plus grande donne une pression plus faible.` },
  { d: 2, t: 'Représenter la tension d’un ressort', fig: SVG(220, 190, `<line x1="30" y1="10" x2="190" y2="10" stroke="#5b6577" stroke-width="4"/><polyline points="110,10 110,22 95,30 125,40 95,50 125,60 95,70 125,80 95,90 125,100 110,108 110,120" fill="none" stroke="#14213d" stroke-width="2"/><rect x="90" y="120" width="40" height="34" fill="#d98200" rx="4"/><text x="140" y="70">l = 14 cm</text><text x="140" y="140">S</text>`),
    q: TX`Un ressort de raideur \(k = 50\ \text{N/m}\) et de longueur à vide \(l_0 = 10\ \text{cm}\) retient un solide S ; sa longueur est \(l = 14\ \text{cm}\).<br>1) Calculer l’allongement puis la tension du ressort.<br>2) Donner les caractéristiques de la force exercée par le ressort sur S et la représenter (1 cm ↔ 1 N).<br>3) Cette action est-elle de contact ou à distance ?`,
    s: TX`1) \(\Delta l = 0{,}04\ \text{m}\) ; \(T = k\,\Delta l = 50\times0{,}04 = 2{,}0\ \text{N}\).<br>2) Point d’application : point d’attache du ressort sur S ; droite d’action : l’axe vertical du ressort ; sens : vers le haut ; intensité 2,0 N : flèche de 2 cm.<br>3) Action de contact, localisée.` },
  { d: 3, t: 'Solide immobile sur un plan incliné rugueux', fig: SVG(420, 170, `<polygon points="20,150 400,150 400,12" fill="#e3e9f3" stroke="#5b6577"/><g transform="rotate(-20 220 100)"><rect x="190" y="76" width="60" height="36" fill="#d98200" rx="4"/></g><text x="64" y="144">α = 20°</text>`),
    q: TX`Un solide de masse \(m = 2{,}0\ \text{kg}\) reste immobile sur un plan incliné de \(\alpha = 20°\) par rapport à l’horizontale. \(g = 10\ \text{N/kg}\).<br>1) Faire l’inventaire des forces. Le solide est soumis à deux forces : que peut-on dire de \(\vec R\) ?<br>2) Calculer \(R\), puis ses composantes \(R_N\) et \(f\).<br>3) Calculer le coefficient de frottement \(k = \tan\varphi\). Le plan est-il rugueux ?`,
    s: TX`1) Le poids \(\vec P\) et la réaction \(\vec R\) du plan. À l’équilibre \(\vec R = -\vec P\) : \(\vec R\) est verticale, vers le haut, \(R = P = 20\ \text{N}\).<br>2) \(R_N = R\cos\alpha = 20\cos20° \approx 18{,}8\ \text{N}\) ; \(f = R\sin\alpha = 20\sin20° \approx 6{,}8\ \text{N}\).<br>3) \(k = \dfrac{f}{R_N} = \tan20° \approx 0{,}36\) : il y a du frottement (sans frottement, le solide glisserait).` },
]);

/* ---------- Principe d’inertie ---------- */
addExos('tc-inertie', [
  { d: 1, t: 'Enregistrement du centre d’inertie', fig: SVG(540, 70, ptsRow(20, 40, [0, 75, 150, 225, 300, 375, 450], 7, `<text x="300" y="66" text-anchor="middle" font-size="11">distance entre deux points : 1,5 cm</text>`)),
    q: TX`On enregistre la position du centre d’inertie G d’un palet sur une table horizontale, toutes les \(\tau = 40\ \text{ms}\).<br>1) Quelle est la nature du mouvement de G ? Justifier.<br>2) Calculer la vitesse de G.<br>3) Que peut-on dire des forces qui s’exercent sur le palet ? Les nommer.`,
    s: TX`1) Points alignés et équidistants : mouvement rectiligne uniforme.<br>2) \(v = \dfrac{1{,}5\times10^{-2}}{40\times10^{-3}} = 0{,}375\ \text{m/s}\).<br>3) D’après le principe d’inertie, elles se compensent : le poids \(\vec P\) et l’action de l’air (ou de la table) \(\vec R\), avec \(\vec P + \vec R = \vec 0\). Le palet est pseudo-isolé.` },
  { d: 2, t: 'Centre d’inertie du système Terre – Lune', fig: SVG(460, 100, ball(70, 50, 36, '#1f6fe0', 'T') + ball(410, 50, 12, '#9aa6bf', 'L') + `<line x1="70" y1="50" x2="410" y2="50" stroke="#9aa6bf" stroke-dasharray="4 4"/><circle cx="85" cy="50" r="4" fill="#d93a4a"/><text x="92" y="44" fill="#d93a4a" font-weight="bold">G ?</text><text x="240" y="90" text-anchor="middle">d = 384 000 km</text>`),
    q: TX`La masse de la Terre est 81 fois celle de la Lune. La distance entre leurs centres est \(d = 384\,000\ \text{km}\) ; \(R_T = 6400\ \text{km}\).<br>1) Écrire la relation barycentrique qui définit le centre d’inertie G du système.<br>2) Calculer la distance \(TG\).<br>3) G est-il à l’intérieur ou à l’extérieur de la Terre ?`,
    s: TX`1) \(M_T\,\overrightarrow{GT} + M_L\,\overrightarrow{GL} = \vec 0\).<br>2) \(TG = \dfrac{M_L}{M_T + M_L}\,d = \dfrac{1}{82}\times384\,000 \approx 4\,680\ \text{km}\).<br>3) \(4680\ \text{km} < 6400\ \text{km}\) : G est à l’intérieur de la Terre.` },
  { d: 2, t: 'Haltère dissymétrique', fig: SVG(420, 90, ball(60, 45, 14, '#1f6fe0', 'A') + ball(360, 45, 24, '#d98200', 'B') + `<line x1="74" y1="45" x2="336" y2="45" stroke="#5b6577" stroke-width="4"/><text x="210" y="84" text-anchor="middle">AB = 40 cm</text>`),
    q: TX`Une haltère est formée de deux boules A (\(m_A = 200\ \text{g}\)) et B (\(m_B = 600\ \text{g}\)) dont les centres sont distants de 40 cm ; la tige a une masse négligeable.<br>1) Déterminer la position du centre d’inertie G.<br>2) On lance l’haltère en la faisant tourner sur une table à coussin d’air horizontale. Décrire la trajectoire de G et celle de A.`,
    s: TX`1) \(AG = \dfrac{m_B}{m_A + m_B}\,AB = \dfrac{600}{800}\times40 = 30\ \text{cm}\) : G est à 30 cm de A et 10 cm de B.<br>2) G (système pseudo-isolé) : droite parcourue à vitesse constante. A tourne autour de G : sa trajectoire est une courbe (cycloïde).` },
  { d: 3, t: 'Le parachutiste', fig: SVG(260, 190, `<path d="M60 70 Q130 -10 200 70 Z" fill="#d93a4a" stroke="#14213d"/><line x1="62" y1="70" x2="130" y2="130" stroke="#5b6577"/><line x1="198" y1="70" x2="130" y2="130" stroke="#5b6577"/><circle cx="130" cy="136" r="7" fill="#ffd27a" stroke="#14213d"/><path d="M130 143v22M130 165l-8 14M130 165l8 14M118 150h24" stroke="#14213d" stroke-width="2"/>`),
    q: TX`Un parachutiste et son équipement (\(m = 90\ \text{kg}\)) descendent verticalement à vitesse constante \(v = 5\ \text{m/s}\). \(g = 10\ \text{N/kg}\).<br>1) Quelles forces s’exercent sur le système {parachutiste + parachute} ?<br>2) Que dit le principe d’inertie ? En déduire l’intensité de la force de résistance de l’air.<br>3) Avant l’ouverture du parachute, la vitesse augmentait : que peut-on dire des forces à ce moment-là ?`,
    s: TX`1) Le poids \(\vec P\) (vertical, vers le bas) et la résistance de l’air \(\vec f\) (verticale, vers le haut).<br>2) Mouvement rectiligne uniforme : les forces se compensent, \(\vec P + \vec f = \vec 0\), donc \(f = P = 900\ \text{N}\).<br>3) La vitesse changeait : les forces ne se compensaient pas (\(P > f\)).` },
]);

/* ---------- Équilibre sous deux forces ---------- */
addExos('tc-2forces', [
  { d: 1, t: 'Le fil à plomb', fig: SVG(220, 170, `<line x1="30" y1="12" x2="190" y2="12" stroke="#5b6577" stroke-width="4"/><line x1="110" y1="12" x2="110" y2="110" stroke="#5b6577" stroke-width="1.5"/><path d="M96 110 h28 l-14 34 z" fill="#5b6577"/><text x="130" y="130">m = 300 g</text>`),
    q: TX`Un fil à plomb est formé d’une masse de 300 g suspendue à un fil. \(g = 9{,}8\ \text{N/kg}\).<br>1) Faire l’inventaire des forces qui s’exercent sur la masse.<br>2) Énoncer la condition d’équilibre et en déduire la direction du fil.<br>3) Calculer la tension du fil et représenter les forces (1 cm ↔ 1 N).`,
    s: TX`1) Le poids \(\vec P\) et la tension \(\vec T\) du fil.<br>2) \(\vec P + \vec T = \vec 0\) avec la même droite d’action : le fil est vertical (direction du poids).<br>3) \(T = P = 0{,}3\times9{,}8 \approx 2{,}9\ \text{N}\) : deux flèches opposées de 2,9 cm.` },
  { d: 2, t: 'Courbe T = f(Δl)', fig: cfig({ w: 400, h: 220, x1: 10, xs: 2, y1: 5, ys: 1, xl: 'Δl (cm)', yl: 'T (N)', f: x => x / 2, ext: (X, Y) => [2, 4, 6, 8].map(x => `<circle cx="${X(x)}" cy="${Y(x / 2)}" r="4" fill="#d93a4a"/>`).join('') }),
    q: TX`On suspend des masses à un ressort et on mesure son allongement ; on obtient la courbe ci-contre.<br>1) Quelle relation lie \(T\) et \(\Delta l\) ?<br>2) Déterminer la raideur \(k\) en N/m.<br>3) Quelle masse faut-il suspendre pour obtenir un allongement de 5 cm ? (\(g = 10\ \text{N/kg}\))`,
    s: TX`1) Droite passant par l’origine : \(T = k\,\Delta l\).<br>2) \(k = \dfrac{4\ \text{N}}{0{,}08\ \text{m}} = 50\ \text{N/m}\).<br>3) \(T = 50\times0{,}05 = 2{,}5\ \text{N} = mg \Rightarrow m = 0{,}25\ \text{kg} = 250\ \text{g}\).` },
  { d: 2, t: 'Un bouchon qui flotte', fig: SVG(300, 140, `<rect x="40" y="60" width="220" height="70" fill="#6aa5ff" opacity=".5"/><line x1="40" y1="60" x2="260" y2="60" stroke="#1f6fe0" stroke-width="2"/><rect x="130" y="40" width="40" height="30" fill="#d98200" stroke="#14213d"/><text x="185" y="52">bouchon</text>`),
    q: TX`Un bouchon de liège de volume \(V = 20\ \text{cm}^3\) et de masse volumique \(\rho = 240\ \text{kg/m}^3\) flotte sur l’eau (\(\rho_{eau} = 1000\ \text{kg/m}^3\), \(g = 10\ \text{N/kg}\)).<br>1) Calculer le poids du bouchon.<br>2) Écrire la condition d’équilibre et en déduire la poussée d’Archimède.<br>3) Calculer le volume immergé.`,
    s: TX`1) \(P = \rho Vg = 240\times20\times10^{-6}\times10 = 0{,}048\ \text{N}\).<br>2) \(\vec P + \vec F_A = \vec 0 \Rightarrow F_A = 0{,}048\ \text{N}\).<br>3) \(V_{im} = \dfrac{F_A}{\rho_{eau}g} = \dfrac{0{,}048}{10^4} = 4{,}8\times10^{-6}\ \text{m}^3 = 4{,}8\ \text{cm}^3\) (24 % du volume).` },
  { d: 3, t: 'Le dynamomètre dans l’eau', fig: SVG(380, 200, `<line x1="30" y1="10" x2="350" y2="10" stroke="#5b6577" stroke-width="4"/><rect x="80" y="10" width="24" height="70" fill="#eaf1fd" stroke="#14213d"/><text x="92" y="50" text-anchor="middle" font-size="10">5,0</text><line x1="92" y1="80" x2="92" y2="110" stroke="#5b6577"/><rect x="78" y="110" width="28" height="28" fill="#9aa6bf"/><text x="92" y="160" text-anchor="middle">dans l’air</text>
      <rect x="250" y="10" width="24" height="70" fill="#eaf1fd" stroke="#14213d"/><text x="262" y="50" text-anchor="middle" font-size="10">3,0</text><line x1="262" y1="80" x2="262" y2="130" stroke="#5b6577"/><rect x="200" y="100" width="124" height="90" fill="#6aa5ff" opacity=".45" stroke="#1f6fe0"/><rect x="248" y="130" width="28" height="28" fill="#9aa6bf"/><text x="262" y="186" text-anchor="middle">dans l’eau</text>`),
    q: TX`Un solide suspendu à un dynamomètre indique 5,0 N dans l’air et 3,0 N lorsqu’il est complètement immergé dans l’eau (\(\rho_{eau} = 1000\ \text{kg/m}^3\), \(g = 10\ \text{N/kg}\)).<br>1) Pourquoi l’indication diminue-t-elle dans l’eau ?<br>2) Calculer la poussée d’Archimède.<br>3) En déduire le volume puis la masse volumique du solide.`,
    s: TX`1) L’eau exerce sur le solide une poussée verticale vers le haut.<br>2) À l’équilibre dans l’eau : \(T + F_A = P\), donc \(F_A = 5{,}0 - 3{,}0 = 2{,}0\ \text{N}\).<br>3) \(V = \dfrac{F_A}{\rho_{eau}g} = 2{,}0\times10^{-4}\ \text{m}^3 = 200\ \text{cm}^3\) ; \(m = \dfrac{P}{g} = 0{,}50\ \text{kg}\) ; \(\rho = \dfrac{m}{V} = 2{,}5\times10^{3}\ \text{kg/m}^3\).` },
]);

/* ---------- Équilibre sous trois forces ---------- */
addExos('tc-3forces', [
  { d: 1, t: 'Construction graphique', fig: SVG(300, 170, ARW('t4') + `<circle cx="150" cy="95" r="10" fill="none" stroke="#14213d" stroke-width="3"/>${VEC(160, 95, 250, 95, 'F₁', '#1f6fe0', 't4')}${VEC(150, 85, 150, 15, 'F₂', '#d93a4a', 't4')}<text x="40" y="160" font-size="11">F₁ ⟂ F₂</text>`),
    q: TX`Un anneau de masse négligeable est en équilibre sous l’action de trois fils. Les forces \(\vec F_1\) (horizontale, 3,0 N) et \(\vec F_2\) (verticale, 4,0 N) sont perpendiculaires.<br>1) Écrire la condition d’équilibre.<br>2) Construire \(\vec F_3\) graphiquement (1 cm ↔ 1 N).<br>3) Calculer \(F_3\) et l’angle de \(\vec F_3\) avec l’horizontale.`,
    s: TX`1) \(\vec F_1 + \vec F_2 + \vec F_3 = \vec 0\), droites d’action concourantes au centre de l’anneau.<br>2) \(\vec F_3 = -(\vec F_1 + \vec F_2)\) : dirigée vers le bas et vers la gauche.<br>3) \(F_3 = \sqrt{3^2 + 4^2} = 5{,}0\ \text{N}\) ; \(\tan\beta = \dfrac{4}{3}\), \(\beta \approx 53°\) sous l’horizontale.` },
  { d: 2, t: 'Un tableau suspendu', fig: SVG(320, 170, `<line x1="20" y1="12" x2="300" y2="12" stroke="#5b6577" stroke-width="4"/><line x1="160" y1="12" x2="110" y2="80" stroke="#5b6577" stroke-width="2"/><line x1="160" y1="12" x2="210" y2="80" stroke="#5b6577" stroke-width="2"/><rect x="90" y="80" width="140" height="80" fill="#ffd27a" stroke="#14213d"/><text x="160" y="125" text-anchor="middle">m = 2,0 kg</text><text x="168" y="40" font-size="11">30°</text>`),
    q: TX`Un tableau de masse \(m = 2{,}0\ \text{kg}\) est suspendu par deux fils symétriques faisant chacun un angle de 30° avec la verticale (\(g = 10\ \text{N/kg}\)). On considère les deux tensions et le poids.<br>1) Écrire la condition d’équilibre.<br>2) Par projection sur la verticale, calculer la tension \(T\) de chaque fil.<br>3) Que devient \(T\) si l’angle augmente ?`,
    s: TX`1) \(\vec P + \vec T_1 + \vec T_2 = \vec 0\).<br>2) Sur l’horizontale, \(T_1 = T_2 = T\) ; sur la verticale : \(2T\cos30° = mg \Rightarrow T = \dfrac{20}{2\times0{,}866} \approx 11{,}5\ \text{N}\).<br>3) \(\cos\theta\) diminue, donc \(T = \dfrac{mg}{2\cos\theta}\) augmente : les fils risquent de casser.` },
  { d: 2, t: 'Boule contre un mur', fig: SVG(260, 200, `<rect x="200" y="0" width="20" height="200" fill="#c9d3e3"/><line x1="200" y1="10" x2="160" y2="120" stroke="#5b6577" stroke-width="2"/>${ball(170, 140, 30, '#1f6fe0', '')}<text x="172" y="40" font-size="11">20°</text><text x="40" y="190" font-size="11">mur vertical lisse</text>`),
    q: TX`Une boule de masse \(m = 1{,}0\ \text{kg}\) est suspendue à un fil et s’appuie contre un mur vertical <b>lisse</b>. Le fil fait un angle \(\alpha = 20°\) avec le mur (\(g = 10\ \text{N/kg}\)).<br>1) Quelles sont les trois forces ? Quelle est la direction de la réaction du mur ?<br>2) Calculer la tension du fil et la réaction du mur.`,
    s: TX`1) Le poids \(\vec P\), la tension \(\vec T\) et la réaction \(\vec R\) du mur ; sans frottement, \(\vec R\) est perpendiculaire au mur : horizontale.<br>2) Verticale : \(T\cos\alpha = mg \Rightarrow T = \dfrac{10}{\cos20°} \approx 10{,}6\ \text{N}\). Horizontale : \(R = T\sin\alpha = mg\tan\alpha \approx 3{,}6\ \text{N}\).` },
  { d: 3, t: 'Wagonnet tiré sur une pente', fig: SVG(440, 190, `<polygon points="20,170 420,170 420,30" fill="#e3e9f3" stroke="#5b6577"/><g transform="rotate(-19.3 230 112)"><rect x="196" y="90" width="70" height="36" fill="#d98200" rx="5"/><line x1="266" y1="104" x2="350" y2="76" stroke="#14213d" stroke-width="2"/></g><text x="66" y="164">α = 30°</text><text x="250" y="40" font-size="11">câble (β = 20° avec la pente)</text>`),
    q: TX`Un wagonnet de masse \(m = 500\ \text{kg}\) est maintenu immobile sur une pente de \(\alpha = 30°\) par un câble faisant un angle \(\beta = 20°\) avec la pente. On néglige les frottements (\(g = 10\ \text{N/kg}\)).<br>1) Représenter les trois forces.<br>2) En projetant sur un axe parallèle à la pente, calculer la tension \(T\) du câble.<br>3) En projetant sur l’axe perpendiculaire, calculer la réaction \(R\) des rails.`,
    s: TX`1) \(\vec P\) vertical vers le bas, \(\vec T\) selon le câble, \(\vec R\) perpendiculaire à la pente.<br>2) \(T\cos\beta - mg\sin\alpha = 0 \Rightarrow T = \dfrac{5000\times0{,}5}{\cos20°} \approx 2{,}66\times10^{3}\ \text{N}\).<br>3) \(R + T\sin\beta - mg\cos\alpha = 0 \Rightarrow R = 5000\times0{,}866 - 2660\times0{,}342 \approx 3{,}42\times10^{3}\ \text{N}\).` },
]);

/* ---------- Équilibre d’un solide en rotation ---------- */
addExos('tc-moment', [
  { d: 1, t: 'Ouvrir une porte', fig: SVG(380, 120, ARW('m4') + `<rect x="40" y="50" width="300" height="14" fill="#d98200"/><circle cx="40" cy="57" r="7" fill="#fff" stroke="#14213d" stroke-width="2"/><text x="20" y="96">gonds (axe Δ)</text>${VEC(280, 64, 280, 112, 'F', '#d93a4a', 'm4')}<text x="160" y="40">80 cm</text><text x="350" y="62" font-size="11">vue de dessus</text>`),
    q: TX`On pousse une porte avec une force \(F = 10\ \text{N}\) perpendiculaire à la porte, à 80 cm de l’axe des gonds.<br>1) Calculer le moment de cette force.<br>2) Quelle force faut-il exercer à 20 cm de l’axe pour obtenir le même moment ?<br>3) Pourquoi la poignée est-elle placée loin des gonds ?`,
    s: TX`1) \(\mathcal M = F\cdot d = 10\times0{,}80 = 8{,}0\ \text{N}\cdot\text{m}\).<br>2) \(F' = \dfrac{8{,}0}{0{,}20} = 40\ \text{N}\).<br>3) Plus le bras de levier est grand, plus la force nécessaire est petite.` },
  { d: 2, t: 'La brouette', fig: SVG(440, 150, ARW('m5') + `${ball(60, 110, 26, '#14213d', '')}<line x1="60" y1="110" x2="400" y2="60" stroke="#5b6577" stroke-width="5"/><path d="M90 60 h120 l-20 40 h-80 z" fill="#d98200"/><circle cx="150" cy="80" r="4" fill="#fff"/><text x="156" y="76" fill="#fff">G</text>${VEC(395, 60, 395, 20, 'F', '#d93a4a', 'm5')}<text x="100" y="140">0,5 m</text><text x="250" y="140">L = 1,5 m (axe → poignées)</text>`),
    q: TX`Une brouette chargée a une masse totale \(m = 60\ \text{kg}\). Son centre de gravité G est à une distance horizontale de 0,5 m de l’axe de la roue ; les poignées sont à 1,5 m de cet axe. \(g = 10\ \text{N/kg}\).<br>1) Quelles forces s’exercent sur la brouette ? Laquelle a un moment nul par rapport à l’axe de la roue ?<br>2) Calculer la force verticale \(F\) que doit exercer le jardinier pour maintenir la brouette en équilibre.<br>3) Calculer la réaction de l’axe.`,
    s: TX`1) Le poids \(\vec P\), la force \(\vec F\) du jardinier et la réaction \(\vec R\) du sol sur la roue ; \(\vec R\) passe par l’axe : moment nul.<br>2) \(F\times1{,}5 - mg\times0{,}5 = 0 \Rightarrow F = \dfrac{600\times0{,}5}{1{,}5} = 200\ \text{N}\).<br>3) \(R = P - F = 600 - 200 = 400\ \text{N}\), verticale vers le haut.` },
  { d: 2, t: 'Le pied-de-biche', fig: SVG(440, 130, ARW('m6') + `<line x1="40" y1="90" x2="400" y2="60" stroke="#5b6577" stroke-width="7" stroke-linecap="round"/><polygon points="80,90 70,112 90,112" fill="#14213d"/><rect x="18" y="56" width="40" height="30" fill="#9aa6bf"/>${VEC(395, 60, 395, 116, 'F', '#d93a4a', 'm6')}<text x="40" y="50" font-size="11">caisse</text><text x="70" y="126" font-size="11">appui O</text><text x="200" y="40" font-size="11">OA = 5 cm ; OB = 60 cm</text>`),
    q: TX`On soulève le couvercle d’une caisse avec un pied-de-biche en appui en O. Le couvercle exerce en A une force verticale \(F_A\) avec \(OA = 5\ \text{cm}\) ; l’ouvrier exerce en B une force verticale \(F = 300\ \text{N}\) avec \(OB = 60\ \text{cm}\) (distances mesurées horizontalement).<br>1) Écrire le théorème des moments par rapport à O.<br>2) Calculer \(F_A\). Quel est l’intérêt de l’outil ?`,
    s: TX`1) \(F\cdot OB - F_A\cdot OA = 0\).<br>2) \(F_A = \dfrac{300\times60}{5} = 3600\ \text{N}\) : l’outil multiplie la force par 12.` },
  { d: 3, t: 'Barre maintenue horizontale', fig: SVG(440, 150, ARW('m7') + `<rect x="40" y="56" width="350" height="12" fill="#d98200"/><polygon points="145,68 133,92 157,92" fill="#14213d"/><text x="138" y="108">O</text><line x1="40" y1="68" x2="40" y2="100" stroke="#5b6577"/><rect x="28" y="100" width="24" height="24" fill="#9aa6bf"/><text x="20" y="50">A</text><text x="392" y="50">B</text>${VEC(390, 56, 390, 20, 'F', '#d93a4a', 'm7')}<text x="70" y="140" font-size="11">AO = 30 cm ; AB = 1,0 m</text>`),
    q: TX`Une barre homogène AB (\(L = 1{,}0\ \text{m}\), \(m = 2{,}0\ \text{kg}\)) peut tourner autour d’un axe horizontal O tel que \(AO = 30\ \text{cm}\). On suspend en A une masse \(m_1 = 1{,}0\ \text{kg}\). Une force verticale \(\vec F\) appliquée en B maintient la barre horizontale. \(g = 10\ \text{N/kg}\).<br>1) Faire l’inventaire des forces et préciser leurs bras de levier.<br>2) Appliquer le théorème des moments et calculer \(F\) ; préciser son sens.<br>3) Calculer la réaction de l’axe.`,
    s: TX`1) Poids de la barre \(P = 20\ \text{N}\) (au milieu, à 0,20 m de O côté B) ; poids de \(m_1\) : 10 N (en A, à 0,30 m de O) ; \(\vec F\) en B (0,70 m) ; réaction \(\vec R\) en O (moment nul).<br>2) En choisissant le sens positif « côté A descend » : \(10\times0{,}30 - 20\times0{,}20 + F\times0{,}70 = 0\) si \(\vec F\) est vers le haut, d’où \(F = \dfrac{4 - 3}{0{,}70} \approx 1{,}4\ \text{N}\), dirigée vers le haut.<br>3) \(R = 20 + 10 - 1{,}4 \approx 28{,}6\ \text{N}\), verticale vers le haut.` },
]);

/* ---------- petits symboles de circuits ---------- */
const W_ = (pts) => `<polyline points="${pts}" fill="none" stroke="#14213d" stroke-width="2"/>`;
const RES = (x, y, lab, v) => v ? `<rect x="${x - 10}" y="${y - 28}" width="20" height="56" fill="#fff" stroke="#14213d" stroke-width="2"/><text x="${x + 16}" y="${y + 4}">${lab}</text>`
  : `<rect x="${x - 28}" y="${y - 10}" width="56" height="20" fill="#fff" stroke="#14213d" stroke-width="2"/><text x="${x}" y="${y - 15}" text-anchor="middle">${lab}</text>`;
const GEN = (x, y, lab, v) => v ? `<rect x="${x - 16}" y="${y - 12}" width="32" height="24" fill="#fff"/><line x1="${x - 16}" y1="${y - 6}" x2="${x + 16}" y2="${y - 6}" stroke="#14213d" stroke-width="2.5"/><line x1="${x - 9}" y1="${y + 6}" x2="${x + 9}" y2="${y + 6}" stroke="#14213d" stroke-width="5"/><text x="${x + 20}" y="${y - 4}">+</text><text x="${x + 20}" y="${y + 22}">${lab || ''}</text>`
  : `<rect x="${x - 12}" y="${y - 16}" width="24" height="32" fill="#fff"/><line x1="${x - 6}" y1="${y - 16}" x2="${x - 6}" y2="${y + 16}" stroke="#14213d" stroke-width="2.5"/><line x1="${x + 6}" y1="${y - 9}" x2="${x + 6}" y2="${y + 9}" stroke="#14213d" stroke-width="5"/><text x="${x - 14}" y="${y - 20}">+</text><text x="${x}" y="${y + 34}" text-anchor="middle">${lab || ''}</text>`;
const LAMP = (x, y, lab) => `<circle cx="${x}" cy="${y}" r="13" fill="#fff" stroke="#14213d" stroke-width="2"/><path d="M${x - 9} ${y - 9}L${x + 9} ${y + 9}M${x + 9} ${y - 9}L${x - 9} ${y + 9}" stroke="#14213d" stroke-width="1.5"/><text x="${x}" y="${y - 18}" text-anchor="middle">${lab || ''}</text>`;
const METER = (x, y, l) => `<circle cx="${x}" cy="${y}" r="13" fill="#fff" stroke="#14213d" stroke-width="2"/><text x="${x}" y="${y + 5}" text-anchor="middle" font-weight="bold">${l}</text>`;
const DIAL = (cal, n, unit) => SVG(300, 150, `<path d="M40 130 A110 110 0 0 1 260 130" fill="none" stroke="#14213d" stroke-width="2"/>${Array.from({ length: 11 }, (_, k) => { const a = Math.PI * (1 - k / 10), c = Math.cos(a), s = Math.sin(a); return `<line x1="${150 + 110 * c}" y1="${130 - 110 * s}" x2="${150 + 98 * c}" y2="${130 - 98 * s}" stroke="#14213d" stroke-width="2"/><text x="${150 + 85 * c}" y="${134 - 85 * s}" text-anchor="middle" font-size="10">${k * 10}</text>`; }).join('')}
  <line x1="150" y1="130" x2="${150 + 105 * Math.cos(Math.PI * (1 - n / 100))}" y2="${130 - 105 * Math.sin(Math.PI * (1 - n / 100))}" stroke="#d93a4a" stroke-width="2.5"/><circle cx="150" cy="130" r="5" fill="#14213d"/><text x="150" y="148" text-anchor="middle" font-size="11">calibre : ${cal} ${unit} — 100 divisions</text>`);
const GRID = (body) => SVG(400, 320, Array.from({ length: 11 }, (_, k) => `<line x1="${k * 40}" y1="0" x2="${k * 40}" y2="320" stroke="#9fb0c8" stroke-width="${k === 5 ? 1.4 : .6}"/>`).join('') + Array.from({ length: 9 }, (_, k) => `<line x1="0" y1="${k * 40}" x2="400" y2="${k * 40}" stroke="#9fb0c8" stroke-width="${k === 4 ? 1.4 : .6}"/>`).join('') + body);
const sinPath = (amp, per, ph) => `<polyline points="${Array.from({ length: 201 }, (_, i) => { const x = i * 2; return x + ',' + (160 - 40 * amp * Math.sin(2 * Math.PI * x / (40 * per) + (ph || 0))).toFixed(1); }).join(' ')}" fill="none" stroke="#1f6fe0" stroke-width="2.5"/>`;

/* ---------- Le courant électrique continu ---------- */
addExos('tc-courant', [
  { d: 1, t: 'Lire un ampèremètre à aiguille', fig: DIAL(300, 64, 'mA'),
    q: TX`L’aiguille d’un ampèremètre (calibre 300 mA, échelle de 100 divisions, classe 1,5) s’arrête sur la division 64.<br>1) Calculer l’intensité mesurée.<br>2) Calculer l’incertitude absolue \(\Delta I = \dfrac{\text{classe}\times\text{calibre}}{100}\) et écrire le résultat.<br>3) Aurait-on pu utiliser le calibre 100 mA ?`,
    s: TX`1) \(I = \dfrac{300\times64}{100} = 192\ \text{mA}\).<br>2) \(\Delta I = \dfrac{1{,}5\times300}{100} = 4{,}5\ \text{mA}\) : \(I = (192 \pm 4{,}5)\ \text{mA}\).<br>3) Non : 192 mA dépasse 100 mA (l’appareil serait hors calibre).` },
  { d: 2, t: 'Appliquer la loi des nœuds', fig: SVG(420, 190, W_('60,40 60,160 360,160 360,40 60,40') + GEN(60, 100, '', 1) + W_('140,40 140,80 280,80 280,40') + W_('140,80 140,120 280,120 280,80') + LAMP(210, 40, 'L₁') + LAMP(210, 80, 'L₂') + LAMP(210, 120, 'L₃') + METER(100, 160, 'A') + `<circle cx="140" cy="40" r="4" fill="#14213d"/><circle cx="140" cy="80" r="4" fill="#14213d"/><circle cx="280" cy="40" r="4" fill="#14213d"/><circle cx="280" cy="80" r="4" fill="#14213d"/><text x="126" y="34">A</text><text x="286" y="34">B</text>`),
    q: TX`Trois lampes sont montées en dérivation. L’ampèremètre de la branche principale indique \(I = 0{,}90\ \text{A}\) ; les lampes \(L_1\) et \(L_2\) sont traversées par \(I_1 = 0{,}25\ \text{A}\) et \(I_2 = 0{,}40\ \text{A}\).<br>1) Énoncer la loi des nœuds et calculer \(I_3\).<br>2) Combien d’électrons traversent la branche principale en une seconde ?<br>3) Que devient \(I\) si on dévisse \(L_3\) ?`,
    s: TX`1) \(I = I_1 + I_2 + I_3 \Rightarrow I_3 = 0{,}90 - 0{,}25 - 0{,}40 = 0{,}25\ \text{A}\).<br>2) \(Q = I\cdot\Delta t = 0{,}90\ \text{C}\) ; \(n = \dfrac{Q}{e} = \dfrac{0{,}90}{1{,}6\times10^{-19}} \approx 5{,}6\times10^{18}\) électrons.<br>3) La branche de \(L_3\) est ouverte : \(I = 0{,}65\ \text{A}\) (les autres lampes ne changent pas).` },
  { d: 2, t: 'Le courant dans une solution', fig: SVG(380, 180, `<rect x="80" y="60" width="220" height="110" fill="#6aa5ff" opacity=".35" stroke="#14213d" stroke-width="2"/><rect x="110" y="40" width="14" height="100" fill="#5b6577"/><rect x="256" y="40" width="14" height="100" fill="#5b6577"/>` + W_('117,40 117,15 263,15 263,40') + GEN(190, 15, '') + `<text x="96" y="160">anode</text><text x="236" y="160">cathode</text><circle cx="160" cy="110" r="8" fill="#d93a4a"/><text x="160" y="114" text-anchor="middle" fill="#fff" font-size="10">+</text><circle cx="220" cy="90" r="8" fill="#1f6fe0"/><text x="220" y="94" text-anchor="middle" fill="#fff" font-size="10">−</text>`),
    q: TX`On fait passer un courant d’intensité constante \(I = 0{,}50\ \text{A}\) pendant 10 min dans une solution de sulfate de cuivre.<br>1) Quels porteurs de charge assurent le passage du courant dans la solution ? dans les fils ?<br>2) Dans quel sens se déplacent les cations ? les anions ?<br>3) Calculer la quantité d’électricité qui a traversé le circuit, puis le nombre d’électrons correspondant.`,
    s: TX`1) Les ions (\(\text{Cu}^{2+}\) et \(\text{SO}_4^{2-}\)) dans la solution ; les électrons libres dans les fils.<br>2) Les cations vont vers la cathode (dans le sens du courant), les anions vers l’anode (sens inverse).<br>3) \(Q = I\,\Delta t = 0{,}50\times600 = 300\ \text{C}\) ; \(n = \dfrac{300}{1{,}6\times10^{-19}} \approx 1{,}9\times10^{21}\) électrons.` },
  { d: 3, t: 'Autonomie d’un téléphone', fig: SVG(300, 120, `<rect x="40" y="25" width="200" height="80" rx="10" fill="#1f6fe0"/><rect x="240" y="50" width="14" height="30" rx="3" fill="#1f6fe0"/><text x="140" y="62" text-anchor="middle" fill="#fff" font-weight="bold">4000 mAh</text><text x="140" y="84" text-anchor="middle" fill="#fff">3,7 V</text>`),
    q: TX`La batterie d’un téléphone porte l’indication « 4000 mAh ».<br>1) Que représente cette grandeur ? La convertir en coulombs.<br>2) Le téléphone consomme en moyenne un courant de 200 mA. Calculer son autonomie.<br>3) Combien d’électrons la batterie peut-elle faire circuler au total ?<br>4) En mode vidéo, l’autonomie n’est plus que de 8 h. Calculer l’intensité moyenne.`,
    s: TX`1) La quantité d’électricité que peut débiter la batterie : \(Q = 4\ \text{A}\times3600\ \text{s} = 14\,400\ \text{C}\).<br>2) \(\Delta t = \dfrac{Q}{I} = \dfrac{4000\ \text{mAh}}{200\ \text{mA}} = 20\ \text{h}\).<br>3) \(n = \dfrac{14\,400}{1{,}6\times10^{-19}} = 9{,}0\times10^{22}\).<br>4) \(I = \dfrac{4000\ \text{mAh}}{8\ \text{h}} = 500\ \text{mA}\).` },
]);

/* ---------- La tension électrique ---------- */
addExos('tc-tension', [
  { d: 1, t: 'Lire un voltmètre à aiguille', fig: DIAL(10, 46, 'V'),
    q: TX`Un voltmètre à aiguille (calibre 10 V, 100 divisions, classe 2) indique la division 46.<br>1) Calculer la tension mesurée.<br>2) Calculer l’incertitude et encadrer la valeur.<br>3) Comment brancher le voltmètre pour mesurer \(U_{AB}\) ?`,
    s: TX`1) \(U = \dfrac{10\times46}{100} = 4{,}6\ \text{V}\).<br>2) \(\Delta U = \dfrac{2\times10}{100} = 0{,}2\ \text{V}\) : \(4{,}4\ \text{V} \le U \le 4{,}8\ \text{V}\).<br>3) En dérivation, borne V en A et borne COM en B.` },
  { d: 2, t: 'Loi des mailles et potentiels', fig: SVG(420, 170, W_('60,30 360,30 360,140 60,140 60,30') + GEN(60, 85, '', 1) + RES(140, 30, 'D₁') + RES(260, 30, 'D₂') + RES(360, 85, 'D₃', 1) + `<text x="40" y="26">P</text><text x="194" y="22">A</text><text x="364" y="22">B</text><text x="40" y="160">N (masse)</text><circle cx="200" cy="30" r="4" fill="#14213d"/><circle cx="360" cy="30" r="4" fill="#14213d"/>`),
    q: TX`Le générateur impose \(U_{PN} = 12\ \text{V}\). On mesure \(U_{PA} = 5\ \text{V}\) et \(U_{AB} = 4\ \text{V}\). On prend N comme masse (\(V_N = 0\)).<br>1) Appliquer la loi des mailles et calculer \(U_{BN}\).<br>2) Calculer les potentiels \(V_P\), \(V_A\) et \(V_B\).<br>3) Que vaut \(U_{AP}\) ?`,
    s: TX`1) \(U_{PN} = U_{PA} + U_{AB} + U_{BN} \Rightarrow U_{BN} = 12 - 5 - 4 = 3\ \text{V}\).<br>2) \(V_P = 12\ \text{V}\) ; \(V_A = V_P - U_{PA} = 7\ \text{V}\) ; \(V_B = V_A - U_{AB} = 3\ \text{V}\).<br>3) \(U_{AP} = -U_{PA} = -5\ \text{V}\).` },
  { d: 2, t: 'Exploiter un oscillogramme', fig: GRID(sinPath(3, 4)),
    q: TX`L’oscillogramme ci-contre est obtenu avec \(S_v = 2\ \text{V/div}\) et \(S_h = 5\ \text{ms/div}\).<br>1) Quelle est la nature de cette tension ?<br>2) Déterminer la tension maximale et la période.<br>3) Calculer la fréquence et la valeur efficace.`,
    s: TX`1) Alternative sinusoïdale.<br>2) \(U_m = 3\ \text{div}\times2 = 6\ \text{V}\) ; \(T = 4\ \text{div}\times5 = 20\ \text{ms}\).<br>3) \(f = \dfrac{1}{0{,}020} = 50\ \text{Hz}\) ; \(U_{eff} = \dfrac{6}{\sqrt2} \approx 4{,}2\ \text{V}\).` },
  { d: 3, t: 'Visualiser la tension du secteur', fig: GRID(sinPath(3.11, 5) + `<text x="6" y="16" font-size="11">S_v = 100 V/div ; S_h = 4 ms/div</text>`),
    q: TX`On visualise (avec un transformateur de sécurité et une sonde adaptée) une tension sinusoïdale de valeur efficace 220 V et de fréquence 50 Hz.<br>1) Calculer \(U_m\) et \(T\).<br>2) Avec \(S_v = 100\ \text{V/div}\), sur combien de divisions s’étend l’amplitude ?<br>3) L’écran a 10 divisions horizontales. Quelle vitesse de balayage permet de voir exactement 2 périodes ?<br>4) Vérifier sur l’oscillogramme.`,
    s: TX`1) \(U_m = 220\sqrt2 \approx 311\ \text{V}\) ; \(T = \dfrac{1}{50} = 20\ \text{ms}\).<br>2) \(y = \dfrac{311}{100} \approx 3{,}1\ \text{div}\).<br>3) \(2T = 40\ \text{ms}\) sur 10 div : \(S_h = 4\ \text{ms/div}\).<br>4) Une période occupe 5 div et l’amplitude un peu plus de 3 div.` },
]);

/* ---------- Association des conducteurs ohmiques ---------- */
addExos('tc-association', [
  { d: 1, t: 'Résistance d’un fil de cuivre', fig: SVG(320, 110, `<ellipse cx="160" cy="55" rx="100" ry="38" fill="none" stroke="#d98200" stroke-width="6"/><ellipse cx="160" cy="55" rx="80" ry="28" fill="none" stroke="#d98200" stroke-width="6"/><text x="160" y="104" text-anchor="middle">L = 100 m ; S = 1,5 mm²</text>`),
    q: TX`Un câble de cuivre (\(\rho = 1{,}7\times10^{-8}\ \Omega\cdot\text{m}\)) a une longueur de 100 m et une section de \(1{,}5\ \text{mm}^2\).<br>1) Calculer sa résistance.<br>2) Que devient-elle si on prend un câble de section \(2{,}5\ \text{mm}^2\) ?<br>3) Pourquoi utilise-t-on des câbles épais pour les appareils puissants ?`,
    s: TX`1) \(R = \rho\dfrac{L}{S} = 1{,}7\times10^{-8}\times\dfrac{100}{1{,}5\times10^{-6}} \approx 1{,}1\ \Omega\).<br>2) \(R' = 1{,}7\times10^{-8}\times\dfrac{100}{2{,}5\times10^{-6}} = 0{,}68\ \Omega\).<br>3) Une plus grande section diminue la résistance, donc l’échauffement des câbles.` },
  { d: 2, t: 'Montage mixte', fig: SVG(440, 160, W_('40,60 100,60') + RES(130, 60, 'R₁ = 100 Ω') + W_('158,60 200,60 200,30 250,30') + W_('200,60 200,100 250,100') + RES(280, 30, 'R₂ = 200 Ω') + RES(280, 100, 'R₃ = 300 Ω') + W_('308,30 350,30 350,100 308,100') + W_('350,60 410,60') + `<text x="30" y="56">A</text><text x="412" y="56">B</text>`),
    q: TX`On applique \(U_{AB} = 11\ \text{V}\) au montage ci-contre.<br>1) Calculer la résistance équivalente de \(R_2\) et \(R_3\), puis celle du montage.<br>2) Calculer l’intensité principale \(I\).<br>3) Calculer \(U_1\) aux bornes de \(R_1\) et la tension aux bornes de \(R_2\).<br>4) Calculer \(I_2\) et \(I_3\) ; vérifier la loi des nœuds.`,
    s: TX`1) \(R_{23} = \dfrac{200\times300}{500} = 120\ \Omega\) ; \(R_{éq} = 100 + 120 = 220\ \Omega\).<br>2) \(I = \dfrac{11}{220} = 0{,}050\ \text{A}\).<br>3) \(U_1 = 100\times0{,}05 = 5\ \text{V}\) ; \(U_2 = 11 - 5 = 6\ \text{V}\).<br>4) \(I_2 = \dfrac{6}{200} = 0{,}030\ \text{A}\) ; \(I_3 = \dfrac{6}{300} = 0{,}020\ \text{A}\) ; \(I_2 + I_3 = 0{,}050\ \text{A} = I\).` },
  { d: 2, t: 'Deux caractéristiques', fig: cfig({ w: 400, h: 230, x1: 0.2, xs: 0.05, y1: 20, ys: 5, xl: 'I (A)', yl: 'U (V)', f: x => 100 * x, fmtx: x => String(x).replace('.', ','),
      ext: (X, Y) => `<line x1="${X(0)}" y1="${Y(0)}" x2="${X(0.2)}" y2="${Y(9.4)}" stroke="#d93a4a" stroke-width="2.6"/><text x="${X(0.17)}" y="${Y(17) - 6}" fill="#1f6fe0" font-weight="bold">D₁</text><text x="${X(0.18)}" y="${Y(8.5) - 8}" fill="#d93a4a" font-weight="bold">D₂</text>` }),
    q: TX`On a tracé les caractéristiques de deux dipôles \(D_1\) et \(D_2\).<br>1) Pourquoi ces dipôles sont-ils des conducteurs ohmiques ?<br>2) Calculer leurs résistances.<br>3) Calculer la résistance équivalente quand on les associe en série, puis en dérivation.`,
    s: TX`1) Les caractéristiques sont des droites passant par l’origine : \(U = RI\).<br>2) \(R_1 = \dfrac{20}{0{,}2} = 100\ \Omega\) ; \(R_2 = \dfrac{9{,}4}{0{,}2} = 47\ \Omega\).<br>3) Série : \(147\ \Omega\) ; dérivation : \(\dfrac{100\times47}{147} \approx 32\ \Omega\).` },
  { d: 3, t: 'Diviseur de tension chargé', fig: SVG(380, 180, W_('60,20 160,20') + RES(160, 55, 'R₁', 1) + W_('160,83 160,97') + RES(160, 125, 'R₂', 1) + W_('160,153 160,170 60,170') + W_('160,90 300,90') + RES(300, 125, 'R_c', 1) + W_('300,153 300,170 160,170') + `<text x="40" y="24">+12 V</text><text x="40" y="174">0 V</text><circle cx="160" cy="90" r="4" fill="#14213d"/><text x="168" y="86">S</text>`),
    q: TX`Un diviseur de tension est formé de \(R_1 = R_2 = 1{,}0\ \text{k}\Omega\) alimentées sous \(U = 12\ \text{V}\).<br>1) Sans charge (\(R_c\) débranchée), calculer la tension de sortie \(U_S\) aux bornes de \(R_2\).<br>2) On branche une charge \(R_c = 1{,}0\ \text{k}\Omega\) aux bornes de \(R_2\). Calculer la nouvelle résistance équivalente entre S et la masse, puis \(U_S\).<br>3) Quelle condition doit vérifier \(R_c\) pour que \(U_S\) change peu ?`,
    s: TX`1) \(U_S = 12\times\dfrac{1}{2} = 6{,}0\ \text{V}\).<br>2) \(R_2 \parallel R_c = 500\ \Omega\) ; \(U_S = 12\times\dfrac{500}{1500} = 4{,}0\ \text{V}\).<br>3) Il faut \(R_c \gg R_2\) (par exemple 100 fois plus grande).` },
]);

/* ---------- Dipôles passifs ---------- */
const AX = (body, xl, yl) => SVG(300, 200, `<line x1="20" y1="100" x2="285" y2="100" stroke="#5b6577" stroke-width="1.5"/><line x1="150" y1="190" x2="150" y2="10" stroke="#5b6577" stroke-width="1.5"/><text x="280" y="116">${xl}</text><text x="156" y="20">${yl}</text>` + body);
addExos('tc-passifs', [
  { d: 1, t: 'Reconnaître des caractéristiques', fig: SVG(640, 210, `<g>${AX('<line x1="40" y1="180" x2="260" y2="20" stroke="#1f6fe0" stroke-width="3"/>', 'I', 'U').replace('<svg', '<svg x="0"')}</g>`.replace(/<\/?svg[^>]*>/g, '') + `<text x="150" y="205" text-anchor="middle" font-weight="bold">(a)</text>`
      + `<g transform="translate(320 0)">${AX('<path d="M30 175 C 100 120, 130 102, 150 100 S 200 80, 270 25" fill="none" stroke="#d93a4a" stroke-width="3"/>', 'U', 'I').replace(/<\/?svg[^>]*>/g, '')}<text x="150" y="205" text-anchor="middle" font-weight="bold">(b)</text></g>`),
    q: TX`On donne deux caractéristiques : (a) \(U = f(I)\) d’un dipôle D₁ et (b) \(I = f(U)\) d’un dipôle D₂.<br>1) Définir un dipôle linéaire et un dipôle symétrique.<br>2) Classer D₁ et D₂ (linéaire ou non, symétrique ou non).<br>3) Lequel peut être un conducteur ohmique ? une lampe ?`,
    s: TX`1) Linéaire : caractéristique droite passant par l’origine. Symétrique : la caractéristique est symétrique par rapport à l’origine (même comportement dans les deux sens).<br>2) D₁ : linéaire et symétrique. D₂ : non linéaire (courbe) mais symétrique.<br>3) D₁ : conducteur ohmique ; D₂ : lampe (sa résistance varie avec l’échauffement).` },
  { d: 2, t: 'Thermistance CTN', fig: cfig({ w: 420, h: 230, x1: 100, xs: 20, y1: 12, ys: 2, xl: 'θ (°C)', yl: 'R (kΩ)', f: T => 10 * Math.exp(-0.0329 * (T - 20)) * (T >= 0 ? 1 : 1) }),
    q: TX`La courbe donne la résistance d’une thermistance CTN en fonction de la température (on lit \(R = 10\ \text{k}\Omega\) à 20 °C et \(R \approx 1{,}4\ \text{k}\Omega\) à 80 °C). On lui applique une tension constante \(U = 5{,}0\ \text{V}\).<br>1) Comment varie R quand la température augmente ?<br>2) Calculer l’intensité à 20 °C puis à 80 °C.<br>3) Expliquer comment ce composant peut servir dans une alarme incendie.`,
    s: TX`1) R diminue quand la température augmente (CTN : coefficient de température négatif).<br>2) \(I_{20} = \dfrac{5}{10\,000} = 0{,}5\ \text{mA}\) ; \(I_{80} = \dfrac{5}{1400} \approx 3{,}6\ \text{mA}\).<br>3) Un échauffement fait fortement augmenter le courant, qui peut commander un transistor ou un relais déclenchant la sonnerie.` },
  { d: 2, t: 'Point de fonctionnement', fig: cfig({ w: 400, h: 230, x1: 1, xs: 0.2, y1: 7, ys: 1, xl: 'I (A)', yl: 'U (V)', f: x => 6 - 2 * x, fmtx: x => String(x).replace('.', ','),
      ext: (X, Y) => `<line x1="${X(0)}" y1="${Y(0)}" x2="${X(0.7)}" y2="${Y(7)}" stroke="#d93a4a" stroke-width="2.6"/><circle cx="${X(0.5)}" cy="${Y(5)}" r="5" fill="#12946a"/><text x="${X(0.5) + 8}" y="${Y(5) + 16}" fill="#12946a" font-weight="bold">P</text><text x="${X(0.85)}" y="${Y(4.3)}" fill="#1f6fe0" font-size="11">générateur</text><text x="${X(0.32)}" y="${Y(4.6)}" fill="#d93a4a" font-size="11">résistor R</text>` }),
    q: TX`On a tracé la caractéristique d’un générateur et celle d’un conducteur ohmique R sur le même graphique.<br>1) Déterminer \(E\) et \(r\) du générateur, puis la valeur de \(R\).<br>2) On branche R aux bornes du générateur. Déterminer graphiquement le point de fonctionnement.<br>3) Retrouver ce résultat par le calcul.`,
    s: TX`1) \(E = 6\ \text{V}\) (pour \(I = 0\)) ; pente \(-2\) donc \(r = 2\ \Omega\). Pour R : \(U = 7\ \text{V}\) pour \(I = 0{,}7\ \text{A}\), \(R = 10\ \Omega\).<br>2) Intersection : \(P(0{,}5\ \text{A} ; 5\ \text{V})\).<br>3) \(E - rI = RI \Rightarrow I = \dfrac{6}{12} = 0{,}5\ \text{A}\), \(U = 10\times0{,}5 = 5\ \text{V}\).` },
  { d: 3, t: 'Protéger une diode', fig: SVG(380, 160, W_('60,30 320,30 320,130 60,130 60,30') + GEN(60, 80, '5 V', 1) + RES(150, 30, 'R') + `<polygon points="240,18 240,42 262,30" fill="#14213d"/><line x1="262" y1="18" x2="262" y2="42" stroke="#14213d" stroke-width="3"/><text x="232" y="60" font-size="11">diode (sens direct)</text>`),
    q: TX`Une diode au silicium (seuil \(U_s = 0{,}7\ \text{V}\), intensité maximale admissible 20 mA) est alimentée en sens direct par un générateur de 5,0 V à travers une résistance R. On utilise le modèle : en conduction, \(U_D = U_s\).<br>1) Pourquoi faut-il une résistance R ?<br>2) Calculer la valeur minimale de R.<br>3) On choisit \(R = 220\ \Omega\). Calculer l’intensité.<br>4) On retourne la diode. Que vaut l’intensité ? la tension aux bornes de R ?`,
    s: TX`1) Sans R, l’intensité serait très grande et détruirait la diode.<br>2) \(5{,}0 = RI + 0{,}7 \Rightarrow R_{min} = \dfrac{4{,}3}{0{,}020} = 215\ \Omega\).<br>3) \(I = \dfrac{4{,}3}{220} \approx 19{,}5\ \text{mA}\).<br>4) La diode est bloquée : \(I = 0\) et \(U_R = 0\) (toute la tension est aux bornes de la diode).` },
]);

/* ---------- Dipôle actif ---------- */
addExos('tc-actif', [
  { d: 1, t: 'Lire la caractéristique d’une pile', fig: cfig({ w: 400, h: 230, x1: 3, xs: 0.5, y1: 10, ys: 2, xl: 'I (A)', yl: 'U (V)', f: x => 9 - 3 * x, fmtx: x => String(x).replace('.', ',') }),
    q: TX`La courbe donne la caractéristique \(U_{PN} = f(I)\) d’une pile.<br>1) Déterminer la f.é.m. \(E\) et l’intensité de court-circuit.<br>2) En déduire la résistance interne \(r\).<br>3) Écrire l’équation de la caractéristique et calculer \(U_{PN}\) pour \(I = 0{,}5\ \text{A}\).`,
    s: TX`1) \(E = 9\ \text{V}\) ; \(I_{cc} = 3\ \text{A}\).<br>2) \(r = \dfrac{E}{I_{cc}} = 3\ \Omega\).<br>3) \(U_{PN} = 9 - 3I\) ; pour \(I = 0{,}5\ \text{A}\) : \(U_{PN} = 7{,}5\ \text{V}\).` },
  { d: 2, t: 'Électrolyseur dans un circuit', fig: SVG(420, 170, W_('60,30 360,30 360,140 60,140 60,30') + GEN(60, 85, 'E, r', 1) + RES(180, 30, 'R = 3 Ω') + `<rect x="330" y="60" width="60" height="50" fill="#6aa5ff" opacity=".4" stroke="#14213d"/><line x1="345" y1="50" x2="345" y2="100" stroke="#5b6577" stroke-width="4"/><line x1="375" y1="50" x2="375" y2="100" stroke="#5b6577" stroke-width="4"/><text x="330" y="128" font-size="11">électrolyseur</text>`),
    q: TX`Un générateur (\(E = 6{,}0\ \text{V}\), \(r = 1{,}0\ \Omega\)) alimente en série une résistance \(R = 3{,}0\ \Omega\) et un électrolyseur (\(E' = 1{,}8\ \text{V}\), \(r' = 2{,}0\ \Omega\)).<br>1) Appliquer la loi de Pouillet et calculer \(I\).<br>2) Calculer la tension aux bornes de l’électrolyseur et celle aux bornes du générateur.<br>3) Que se passe-t-il si on remplace le générateur par une pile de 1,5 V ?`,
    s: TX`1) \(I = \dfrac{E - E'}{r + R + r'} = \dfrac{6{,}0 - 1{,}8}{6{,}0} = 0{,}70\ \text{A}\).<br>2) \(U_{él} = E' + r'I = 1{,}8 + 1{,}4 = 3{,}2\ \text{V}\) ; \(U_{PN} = E - rI = 5{,}3\ \text{V}\).<br>3) \(1{,}5\ \text{V} < E'\) : l’électrolyseur ne fonctionne pas, \(I = 0\).` },
  { d: 2, t: 'Piles en série', fig: SVG(420, 120, GEN(80, 50, '') + GEN(150, 50, '') + GEN(220, 50, '') + W_('20,50 68,50') + W_('92,50 138,50') + W_('162,50 208,50') + W_('232,50 280,50') + RES(320, 50, 'R') + W_('348,50 400,50 400,100 20,100 20,50') + `<text x="150" y="20" text-anchor="middle" font-size="11">3 piles : E = 1,5 V ; r = 0,5 Ω</text>`),
    q: TX`Trois piles identiques (\(E = 1{,}5\ \text{V}\), \(r = 0{,}5\ \Omega\)) sont associées en série et alimentent \(R = 7{,}5\ \Omega\).<br>1) Calculer la f.é.m. et la résistance interne du générateur équivalent.<br>2) Calculer l’intensité.<br>3) Par erreur, une pile est montée à l’envers. Calculer la nouvelle intensité.`,
    s: TX`1) \(E_{éq} = 4{,}5\ \text{V}\) ; \(r_{éq} = 1{,}5\ \Omega\).<br>2) \(I = \dfrac{4{,}5}{7{,}5 + 1{,}5} = 0{,}50\ \text{A}\).<br>3) \(E_{éq} = 1{,}5 + 1{,}5 - 1{,}5 = 1{,}5\ \text{V}\) (la résistance interne reste 1,5 Ω) : \(I = \dfrac{1{,}5}{9} \approx 0{,}17\ \text{A}\).` },
  { d: 3, t: 'Le moteur bloqué', fig: SVG(380, 160, W_('60,30 320,30 320,130 60,130 60,30') + GEN(60, 80, '12 V ; 1 Ω', 1) + `<circle cx="320" cy="80" r="20" fill="#fff" stroke="#14213d" stroke-width="2"/><text x="320" y="86" text-anchor="middle" font-weight="bold">M</text>` + METER(190, 130, 'A')),
    q: TX`Un générateur (\(E = 12\ \text{V}\), \(r = 1{,}0\ \Omega\)) alimente un moteur de résistance interne \(r' = 2{,}0\ \Omega\).<br>1) On empêche le moteur de tourner : sa f.c.é.m. est nulle. Calculer l’intensité.<br>2) Le moteur tourne librement : l’ampèremètre indique 1,0 A. Calculer sa f.c.é.m. \(E'\).<br>3) Pourquoi un moteur bloqué risque-t-il de chauffer ?`,
    s: TX`1) \(I = \dfrac{12}{1 + 2} = 4{,}0\ \text{A}\).<br>2) \(I = \dfrac{E - E'}{r + r'} \Rightarrow E' = 12 - 3\times1{,}0 = 9{,}0\ \text{V}\).<br>3) Bloqué, l’intensité est 4 fois plus grande : toute l’énergie est dissipée en chaleur dans les résistances.` },
]);

/* ---------- Le transistor ---------- */
const NPN = (x, y) => `<circle cx="${x}" cy="${y}" r="30" fill="#fff" stroke="#14213d" stroke-width="2"/><line x1="${x - 40}" y1="${y}" x2="${x - 12}" y2="${y}" stroke="#14213d" stroke-width="2"/><line x1="${x - 12}" y1="${y - 16}" x2="${x - 12}" y2="${y + 16}" stroke="#14213d" stroke-width="4"/><line x1="${x - 12}" y1="${y - 8}" x2="${x + 12}" y2="${y - 26}" stroke="#14213d" stroke-width="2"/><line x1="${x - 12}" y1="${y + 8}" x2="${x + 12}" y2="${y + 26}" stroke="#14213d" stroke-width="2"/><polygon points="${x + 12},${y + 26} ${x + 2},${y + 24} ${x + 8},${y + 16}" fill="#14213d"/>`;
addExos('tc-transistor', [
  { d: 1, t: 'Courants dans un transistor', fig: SVG(300, 160, NPN(150, 80) + `<line x1="162" y1="54" x2="162" y2="10" stroke="#14213d" stroke-width="2"/><line x1="162" y1="106" x2="162" y2="150" stroke="#14213d" stroke-width="2"/><text x="96" y="74">B</text><text x="170" y="22">C</text><text x="170" y="146">E</text><text x="20" y="96" font-size="11">I_B = 40 µA</text><text x="190" y="40" font-size="11">I_C = 6,0 mA</text>`),
    q: TX`Dans un transistor NPN, on mesure \(I_B = 40\ \mu\text{A}\) et \(I_C = 6{,}0\ \text{mA}\).<br>1) Nommer les trois bornes.<br>2) Calculer \(I_E\).<br>3) Calculer le gain en courant \(\beta\).`,
    s: TX`1) Base B, collecteur C, émetteur E (la flèche est sur l’émetteur).<br>2) \(I_E = I_B + I_C = 0{,}040 + 6{,}0 = 6{,}04\ \text{mA}\).<br>3) \(\beta = \dfrac{I_C}{I_B} = \dfrac{6{,}0\times10^{-3}}{40\times10^{-6}} = 150\).` },
  { d: 2, t: 'Courbe I_C = f(I_B)', fig: cfig({ w: 420, h: 230, x1: 0.25, xs: 0.05, y1: 25, ys: 5, xl: 'I_B (mA)', yl: 'I_C (mA)', f: x => Math.min(150 * x, 20), fmtx: x => String(x).replace('.', ',') }),
    q: TX`La courbe donne \(I_C\) en fonction de \(I_B\) pour un transistor monté avec une résistance de collecteur.<br>1) Identifier les deux régimes de fonctionnement.<br>2) Déterminer \(\beta\) et \(I_{Csat}\).<br>3) À partir de quelle valeur de \(I_B\) le transistor est-il saturé ?`,
    s: TX`1) Régime linéaire (droite) puis saturation (palier).<br>2) \(\beta = \dfrac{15}{0{,}10} = 150\) ; \(I_{Csat} = 20\ \text{mA}\).<br>3) \(I_B = \dfrac{20}{150} \approx 0{,}13\ \text{mA}\).` },
  { d: 2, t: 'Linéaire ou saturé ?', fig: SVG(420, 190, NPN(260, 100) + `<line x1="272" y1="74" x2="272" y2="30" stroke="#14213d" stroke-width="2"/>` + RES(272, 50, '', 1).replace(/<text.*<\/text>/, '') + `<text x="290" y="54">R_C = 450 Ω</text><line x1="272" y1="20" x2="380" y2="20" stroke="#14213d" stroke-width="2"/><text x="384" y="24">+9 V</text><line x1="272" y1="126" x2="272" y2="170" stroke="#14213d" stroke-width="2"/><text x="262" y="186">0 V</text>` + W_('60,100 220,100') + RES(150, 100, 'R_B') + `<text x="20" y="104">+5 V</text>`),
    q: TX`Montage : \(E = 9{,}0\ \text{V}\), \(R_C = 450\ \Omega\), \(\beta = 100\) ; la base est reliée à +5,0 V par \(R_B\) ; \(U_{BE} = 0{,}7\ \text{V}\) en conduction.<br>1) Calculer \(I_{Csat} \approx E/R_C\).<br>2) Pour \(R_B = 47\ \text{k}\Omega\), calculer \(I_B\) puis \(\beta I_B\). Quel est le régime ? Calculer \(U_{CE}\).<br>3) Même question pour \(R_B = 10\ \text{k}\Omega\).`,
    s: TX`1) \(I_{Csat} = \dfrac{9}{450} = 20\ \text{mA}\).<br>2) \(I_B = \dfrac{5 - 0{,}7}{47\,000} \approx 91\ \mu\text{A}\) ; \(\beta I_B \approx 9{,}1\ \text{mA} < 20\ \text{mA}\) : régime linéaire, \(I_C = 9{,}1\ \text{mA}\) ; \(U_{CE} = 9 - 450\times0{,}0091 \approx 4{,}9\ \text{V}\).<br>3) \(I_B = 0{,}43\ \text{mA}\), \(\beta I_B = 43\ \text{mA} > 20\ \text{mA}\) : saturé, \(I_C = 20\ \text{mA}\) et \(U_{CE} \approx 0\).` },
  { d: 3, t: 'Alarme incendie', fig: SVG(420, 200, `<line x1="80" y1="15" x2="380" y2="15" stroke="#14213d" stroke-width="2"/><text x="384" y="19">+9 V</text>` + RES(80, 55, 'CTN', 1) + W_('80,15 80,27') + W_('80,83 80,117') + RES(80, 145, '2,2 kΩ', 1) + W_('80,173 80,190 380,190') + W_('80,100 228,100') + `<circle cx="80" cy="100" r="4" fill="#14213d"/>` + NPN(268, 100) + `<line x1="280" y1="74" x2="280" y2="15" stroke="#14213d" stroke-width="2"/><rect x="266" y="34" width="28" height="22" fill="#ffd27a" stroke="#14213d"/><text x="300" y="50">sonnerie</text><line x1="280" y1="126" x2="280" y2="190" stroke="#14213d" stroke-width="2"/>`),
    q: TX`La base du transistor est reliée au point commun d’une thermistance CTN et d’une résistance de 2,2 kΩ, alimentées sous 9,0 V. On admet que le transistor conduit quand la tension base–masse atteint 0,7 V, et on néglige le courant de base dans le calcul du diviseur.<br>1) À 20 °C, \(R_{CTN} = 30\ \text{k}\Omega\). Calculer la tension de la base. La sonnerie fonctionne-t-elle ?<br>2) Lors d’un incendie, la CTN atteint 80 °C et \(R_{CTN} = 4{,}0\ \text{k}\Omega\). Même question.<br>3) Quel rôle joue le transistor ?`,
    s: TX`1) \(V_B = 9\times\dfrac{2{,}2}{30 + 2{,}2} \approx 0{,}61\ \text{V} < 0{,}7\ \text{V}\) : transistor bloqué, pas de sonnerie.<br>2) \(V_B = 9\times\dfrac{2{,}2}{4{,}0 + 2{,}2} \approx 3{,}2\ \text{V} > 0{,}7\ \text{V}\) : le transistor conduit, la sonnerie retentit.<br>3) Il fonctionne en interrupteur commandé par la température : un faible courant de base commande le courant de la sonnerie.` },
]);

/* ---------- L’amplificateur opérationnel ---------- */
const AOP = (x, y) => `<polygon points="${x},${y - 40} ${x},${y + 40} ${x + 80},${y}" fill="#fff" stroke="#14213d" stroke-width="2"/><text x="${x + 6}" y="${y - 16}">−</text><text x="${x + 6}" y="${y + 24}">+</text>`;
addExos('tc-aop', [
  { d: 1, t: 'Montage non inverseur', fig: SVG(440, 200, AOP(160, 110) + W_('60,130 160,130') + W_('240,110 380,110') + W_('160,90 130,90 130,40 200,40') + RES(230, 40, 'R₂') + W_('258,40 300,40 300,110') + W_('130,90 130,140') + RES(130, 160, 'R₁', 1).replace('x="146"', 'x="100"') + `<line x1="130" y1="188" x2="130" y2="196" stroke="#14213d" stroke-width="2"/><text x="40" y="126">Uₑ</text><text x="384" y="106">Uₛ</text>`),
    q: TX`On réalise le montage ci-contre avec \(R_1 = 1{,}0\ \text{k}\Omega\) et \(R_2 = 4{,}7\ \text{k}\Omega\) (AOP idéal, \(U_{sat} = 14\ \text{V}\)).<br>1) Nommer ce montage. Fonctionne-t-il en régime linéaire ?<br>2) Calculer son amplification.<br>3) Calculer \(U_s\) pour \(U_e = 1{,}5\ \text{V}\) puis pour \(U_e = 3{,}0\ \text{V}\).`,
    s: TX`1) Amplificateur non inverseur ; la sortie est reliée à \(E^-\) par \(R_2\) (contre-réaction) : régime linéaire.<br>2) \(A = 1 + \dfrac{R_2}{R_1} = 5{,}7\).<br>3) \(U_s = 5{,}7\times1{,}5 \approx 8{,}6\ \text{V}\) ; pour 3,0 V le calcul donne 17,1 V > 14 V : la sortie sature à 14 V.` },
  { d: 2, t: 'Le montage suiveur', fig: SVG(380, 160, AOP(140, 90) + W_('40,110 140,110') + W_('220,90 330,90') + W_('140,70 120,70 120,25 270,25 270,90') + `<text x="20" y="106">Uₑ</text><text x="334" y="86">Uₛ</text>`),
    q: TX`Dans le montage ci-contre, la sortie est reliée directement à l’entrée inverseuse.<br>1) Montrer que \(U_s = U_e\).<br>2) Quel est l’intérêt de ce montage puisqu’il n’amplifie pas ?<br>3) \(U_e\) est sinusoïdale d’amplitude 3 V. Décrire \(U_s\).`,
    s: TX`1) Régime linéaire : \(V_{E^+} = V_{E^-}\) ; or \(V_{E^+} = U_e\) et \(V_{E^-} = U_s\), donc \(U_s = U_e\).<br>2) Le courant d’entrée est nul : le montage ne perturbe pas la source (adaptation d’impédance) tout en pouvant fournir du courant à la charge.<br>3) Même sinusoïde, même amplitude 3 V, en phase.` },
  { d: 2, t: 'Caractéristique de transfert', fig: SVG(360, 260, `<line x1="20" y1="130" x2="340" y2="130" stroke="#5b6577" stroke-width="1.5"/><line x1="180" y1="250" x2="180" y2="10" stroke="#5b6577" stroke-width="1.5"/><text x="330" y="148">Uₑ (V)</text><text x="186" y="20">Uₛ (V)</text>${[-6, -3, 3, 6].map(v => `<line x1="${180 + v * 25}" y1="126" x2="${180 + v * 25}" y2="134" stroke="#5b6577"/><text x="${180 + v * 25}" y="148" text-anchor="middle" font-size="11">${v}</text>`).join('')}${[-12, 12].map(v => `<line x1="176" y1="${130 - v * 8}" x2="184" y2="${130 - v * 8}" stroke="#5b6577"/><text x="168" y="${134 - v * 8}" text-anchor="end" font-size="11">${v}</text>`).join('')}<polyline points="30,34 105,34 255,226 330,226" fill="none" stroke="#1f6fe0" stroke-width="3"/>`),
    q: TX`On a tracé \(U_s = f(U_e)\) pour un amplificateur inverseur.<br>1) Identifier les zones de fonctionnement linéaire et saturé.<br>2) Déterminer \(U_{sat}\) et l’amplification.<br>3) Avec \(R_1 = 10\ \text{k}\Omega\), calculer \(R_2\).<br>4) Que vaut \(U_s\) pour \(U_e = 5\ \text{V}\) ?`,
    s: TX`1) Linéaire pour \(-3\ \text{V} \le U_e \le 3\ \text{V}\) ; saturé au-delà.<br>2) \(U_{sat} = 12\ \text{V}\) ; pente \(\dfrac{-12}{3} = -4\).<br>3) \(\dfrac{R_2}{R_1} = 4 \Rightarrow R_2 = 40\ \text{k}\Omega\).<br>4) Saturation : \(U_s = -12\ \text{V}\).` },
  { d: 3, t: 'Le comparateur', fig: GRID(sinPath(2, 8) + `<line x1="0" y1="120" x2="400" y2="120" stroke="#d93a4a" stroke-width="2" stroke-dasharray="6 4"/><text x="6" y="114" fill="#d93a4a" font-size="11">U_ref = 1 V</text><text x="6" y="16" font-size="11">S_v = 1 V/div</text>`),
    q: TX`Un AOP sans contre-réaction reçoit sur \(E^+\) une tension sinusoïdale \(u_e\) d’amplitude 2 V et sur \(E^-\) une tension constante \(U_{ref} = 1\ \text{V}\) (\(U_{sat} = 14\ \text{V}\)).<br>1) Dans quel régime fonctionne l’AOP ? Donner \(U_s\) selon le signe de \(\varepsilon = u_e - U_{ref}\).<br>2) Pour quelles valeurs de l’angle \(\omega t\) a-t-on \(u_e > 1\ \text{V}\) sur une période ?<br>3) En déduire la fraction de la période pendant laquelle \(U_s = +14\ \text{V}\) et dessiner \(U_s(t)\).`,
    s: TX`1) Régime saturé : \(U_s = +14\ \text{V}\) si \(u_e > 1\ \text{V}\), \(U_s = -14\ \text{V}\) sinon.<br>2) \(2\sin(\omega t) > 1 \iff \sin(\omega t) > \tfrac{1}{2} \iff 30° < \omega t < 150°\).<br>3) \(\dfrac{120°}{360°} = \dfrac{1}{3}\) de la période : un signal rectangulaire, à +14 V pendant \(T/3\) et à −14 V pendant \(2T/3\).` },
]);

/* ================= Chimie du Tronc Commun ================= */
const TUBE = (x, lab, col, h) => `<rect x="${x - 14}" y="20" width="28" height="100" rx="12" fill="#fff" stroke="#14213d" stroke-width="2"/><rect x="${x - 12}" y="${120 - (h || 50)}" width="24" height="${(h || 50) - 2}" rx="10" fill="${col}"/><text x="${x}" y="140" text-anchor="middle" font-weight="bold">${lab}</text>`;

/* ---------- Les espèces chimiques ---------- */
addExos('tcc-especes', [
  { d: 1, t: 'Résultats de tests', fig: SVG(420, 150, TUBE(60, '1', '#1f6fe0') + TUBE(160, '2', '#eef2f8') + TUBE(260, '3', '#c0392b') + TUBE(360, '4', '#1b2a6b')),
    q: TX`On réalise quatre tests sur des aliments ; les tubes montrent le résultat obtenu :<br>(1) sulfate de cuivre anhydre + jus d’orange → bleu ; (2) eau de chaux + gaz expiré → trouble blanc ; (3) liqueur de Fehling chauffée + jus de raisin → précipité rouge brique ; (4) eau iodée + mie de pain → bleu foncé.<br>Quelle espèce chimique chaque test met-il en évidence ?`,
    s: TX`(1) l’eau ; (2) le dioxyde de carbone ; (3) le glucose ; (4) l’amidon.` },
  { d: 2, t: 'Courbe de refroidissement', fig: cfig({ w: 420, h: 230, x1: 20, xs: 4, y1: 100, ys: 20, xl: 't (min)', yl: 'θ (°C)', f: t => t < 5 ? 98 - 3.6 * t : t < 13 ? 80 : 80 - 4 * (t - 13) }),
    q: TX`On laisse refroidir du naphtalène liquide et on relève sa température.<br>1) Décrire les trois parties de la courbe et l’état physique du naphtalène dans chacune.<br>2) Déterminer sa température de solidification. Le naphtalène est-il un corps pur ?<br>3) Quelle serait l’allure de la courbe pour un mélange ?`,
    s: TX`1) De 0 à 5 min : liquide qui refroidit ; de 5 à 13 min : palier, liquide + solide (solidification) ; après 13 min : solide qui refroidit.<br>2) \(\theta = 80\ °\text{C}\) ; le palier montre que c’est un corps pur.<br>3) Pas de palier net : la température diminue pendant la solidification.` },
  { d: 2, t: 'Trois liquides dans une éprouvette', fig: SVG(240, 200, `<rect x="90" y="10" width="60" height="180" rx="6" fill="#fff" stroke="#14213d" stroke-width="2"/><rect x="92" y="40" width="56" height="45" fill="#ffd27a"/><rect x="92" y="85" width="56" height="50" fill="#6aa5ff" opacity=".6"/><rect x="92" y="135" width="56" height="52" fill="#d9e4f5"/><text x="160" y="66">A</text><text x="160" y="114">B</text><text x="160" y="166">C</text>`),
    q: TX`On verse dans une éprouvette de l’eau (\(d = 1{,}00\)), de l’huile (\(d = 0{,}92\)) et du dichlorométhane (\(d = 1{,}33\)), trois liquides non miscibles entre eux.<br>1) Identifier les phases A, B et C.<br>2) Calculer la masse de 25 mL de dichlorométhane.<br>3) Qu’observerait-on en ajoutant de l’éthanol, miscible à l’eau ?`,
    s: TX`1) Du moins dense (en haut) au plus dense : A = huile, B = eau, C = dichlorométhane.<br>2) \(\rho = 1{,}33\ \text{g/mL}\) : \(m = 1{,}33\times25 \approx 33\ \text{g}\).<br>3) L’éthanol se mélange à l’eau : la phase B augmente de volume (pas de nouvelle phase).` },
  { d: 3, t: 'Identifier un liquide inconnu', fig: SVG(420, 130, `<rect x="10" y="10" width="400" height="110" fill="none" stroke="#14213d"/><line x1="10" y1="40" x2="410" y2="40" stroke="#14213d"/>${[150, 280].map(x => `<line x1="${x}" y1="10" x2="${x}" y2="120" stroke="#14213d"/>`).join('')}<text x="80" y="30" text-anchor="middle" font-weight="bold">espèce</text><text x="215" y="30" text-anchor="middle" font-weight="bold">ρ (g/mL)</text><text x="345" y="30" text-anchor="middle" font-weight="bold">θ_éb (°C)</text>${[['éthanol', '0,79', '78'], ['acétone', '0,79', '56'], ['cyclohexane', '0,78', '81']].map((r, k) => r.map((c, j) => `<text x="${[80, 215, 345][j]}" y="${66 + k * 24}" text-anchor="middle">${c}</text>`).join('')).join('')}`),
    q: TX`Un liquide incolore inconnu a une masse de 15,8 g pour un volume de 20,0 mL. Il bout à 78 °C et se mélange à l’eau en toutes proportions.<br>1) Calculer sa masse volumique et sa densité.<br>2) Peut-on l’identifier avec la seule masse volumique ? Justifier.<br>3) Identifier ce liquide.<br>4) Ce liquide pourrait-il servir de solvant extracteur pour une espèce dissoute dans l’eau ?`,
    s: TX`1) \(\rho = \dfrac{15{,}8}{20{,}0} = 0{,}79\ \text{g/mL}\) ; \(d = 0{,}79\).<br>2) Non : l’éthanol et l’acétone ont la même masse volumique (et le cyclohexane est très proche).<br>3) Avec la température d’ébullition 78 °C : c’est l’éthanol.<br>4) Non : il est miscible à l’eau, on ne pourrait pas séparer les phases.` },
]);

/* ---------- Synthèse ---------- */
addExos('tcc-synthese', [
  { d: 1, t: 'Légender le montage à reflux', fig: SVG(320, 230, `<ellipse cx="150" cy="180" rx="45" ry="35" fill="#e3e9f3" stroke="#14213d" stroke-width="2"/><rect x="138" y="115" width="24" height="40" fill="#e3e9f3" stroke="#14213d" stroke-width="2"/>${[0, 1, 2, 3].map(k => `<circle cx="150" cy="${100 - k * 22}" r="11" fill="#eaf1fd" stroke="#14213d" stroke-width="2"/>`).join('')}<path d="M162 104 h40M162 44 h40" stroke="#1f6fe0" stroke-width="2"/><rect x="110" y="212" width="80" height="12" fill="#d93a4a"/><circle cx="140" cy="190" r="3" fill="#5b6577"/><circle cx="156" cy="196" r="3" fill="#5b6577"/>
      <text x="210" y="70" font-weight="bold">(1)</text><text x="208" y="48" font-weight="bold">(2)</text><text x="208" y="108" font-weight="bold">(3)</text><text x="60" y="184" font-weight="bold">(4)</text><text x="200" y="222" font-weight="bold">(5)</text><text x="168" y="200" font-weight="bold">(6)</text>`),
    q: TX`1) Nommer les éléments numérotés : (1) le tube à boules, (2) et (3) les tubulures, (4) le récipient, (5) l’appareil de chauffage, (6) les petits grains.<br>2) Par où l’eau froide doit-elle entrer ? Pourquoi ?<br>3) Quel est le rôle de ce montage ?`,
    s: TX`1) (1) réfrigérant à boules ; (2) entrée d’eau froide ; (3) sortie d’eau ; (4) ballon contenant le mélange réactionnel ; (5) chauffe-ballon ; (6) pierre ponce.<br>2) Par le bas du réfrigérant (ici la tubulure du bas) pour qu’il soit rempli d’eau.<br>3) Chauffer pour accélérer la réaction en condensant les vapeurs, qui retombent dans le ballon : pas de perte de matière.` },
  { d: 2, t: 'Comparer par CCM', fig: SVG(240, 230, `<rect x="40" y="10" width="160" height="210" fill="#fbfcfe" stroke="#14213d" stroke-width="2"/><line x1="40" y1="190" x2="200" y2="190" stroke="#5b6577" stroke-dasharray="4 3"/><line x1="40" y1="40" x2="200" y2="40" stroke="#d93a4a" stroke-dasharray="4 3"/><text x="206" y="44" font-size="11" fill="#d93a4a">front</text>${[[80, [100]], [120, [100, 145]], [160, [100]]].map(([x, ys]) => ys.map(y => `<ellipse cx="${x}" cy="${y}" rx="9" ry="6" fill="#7a4fd6"/>`).join('') + `<circle cx="${x}" cy="190" r="3" fill="#14213d"/>`).join('')}<text x="80" y="210" text-anchor="middle">N</text><text x="120" y="210" text-anchor="middle">S</text><text x="160" y="210" text-anchor="middle">R</text>`),
    q: TX`On compare par CCM une espèce extraite d’une plante (N), un produit de synthèse (S) et l’espèce pure de référence (R). Ligne de dépôt à 1,0 cm du bas ; front de l’éluant à 8,5 cm du bas ; la tache principale est à 5,3 cm du bas.<br>1) Le produit de synthèse est-il pur ? Contient-il l’espèce attendue ?<br>2) Calculer le \(R_f\) de l’espèce attendue.<br>3) L’espèce synthétique est-elle identique à l’espèce naturelle ?`,
    s: TX`1) S présente deux taches : il n’est pas pur ; l’une est à la hauteur de R : il contient l’espèce attendue.<br>2) \(h = 5{,}3 - 1{,}0 = 4{,}3\ \text{cm}\) ; \(H = 8{,}5 - 1{,}0 = 7{,}5\ \text{cm}\) ; \(R_f \approx 0{,}57\).<br>3) Oui : même \(R_f\) que N et R ; il faut cependant purifier le produit.` },
  { d: 2, t: 'Synthèse de l’aspirine', fig: SVG(380, 120, `<rect x="20" y="30" width="100" height="60" rx="10" fill="#eaf1fd" stroke="#14213d"/><text x="70" y="56" text-anchor="middle" font-size="11">acide</text><text x="70" y="72" text-anchor="middle" font-size="11">salicylique</text><text x="150" y="66" font-size="22">→</text><rect x="200" y="30" width="100" height="60" rx="10" fill="#fff7e6" stroke="#14213d"/><text x="250" y="64" text-anchor="middle" font-size="12">aspirine</text><text x="20" y="112" font-size="11">M = 138 g/mol</text><text x="200" y="112" font-size="11">M = 180 g/mol</text>`),
    q: TX`On synthétise l’aspirine à partir de 5,0 g d’acide salicylique (réactif limitant). Une mole d’acide salicylique donne au maximum une mole d’aspirine. On obtient 4,9 g d’aspirine purifiée.<br>1) Calculer la quantité de matière d’acide salicylique.<br>2) Calculer la masse maximale d’aspirine.<br>3) Calculer le rendement. Pourquoi est-il inférieur à 100 % ?`,
    s: TX`1) \(n = \dfrac{5{,}0}{138} \approx 3{,}6\times10^{-2}\ \text{mol}\).<br>2) \(m_{max} = 3{,}6\times10^{-2}\times180 \approx 6{,}5\ \text{g}\).<br>3) \(r = \dfrac{4{,}9}{6{,}5} \approx 75\ \%\) : pertes lors de la filtration et de la purification, réaction incomplète.` },
  { d: 3, t: 'Arôme de banane : réactif limitant', fig: SVG(420, 130, `<rect x="10" y="10" width="400" height="110" fill="none" stroke="#14213d"/><line x1="10" y1="40" x2="410" y2="40" stroke="#14213d"/>${[170, 290].map(x => `<line x1="${x}" y1="10" x2="${x}" y2="120" stroke="#14213d"/>`).join('')}<text x="90" y="30" text-anchor="middle" font-weight="bold">espèce</text><text x="230" y="30" text-anchor="middle" font-weight="bold">M (g/mol)</text><text x="350" y="30" text-anchor="middle" font-weight="bold">ρ (g/mL)</text>${[['alcool isoamylique', '88', '0,81'], ['acide acétique', '60', '1,05'], ['acétate d’isoamyle', '130', '0,87']].map((r, k) => r.map((c, j) => `<text x="${[90, 230, 350][j]}" y="${66 + k * 24}" text-anchor="middle">${c}</text>`).join('')).join('')}`),
    q: TX`On chauffe à reflux 20,0 mL d’alcool isoamylique et 30,0 mL d’acide acétique. L’équation est : alcool + acide → acétate d’isoamyle + eau (coefficients 1). On obtient 16,0 g d’ester.<br>1) Calculer les quantités initiales des réactifs.<br>2) Déterminer le réactif limitant et l’avancement maximal.<br>3) Calculer la masse maximale d’ester et le rendement.`,
    s: TX`1) Alcool : \(n = \dfrac{0{,}81\times20{,}0}{88} \approx 0{,}184\ \text{mol}\) ; acide : \(n = \dfrac{1{,}05\times30{,}0}{60} \approx 0{,}525\ \text{mol}\).<br>2) Coefficients égaux : l’alcool est limitant, \(x_{max} = 0{,}184\ \text{mol}\).<br>3) \(m_{max} = 0{,}184\times130 \approx 23{,}9\ \text{g}\) ; \(r = \dfrac{16{,}0}{23{,}9} \approx 67\ \%\).` },
]);

/* ---------- Modèle de l’atome ---------- */
addExos('tcc-atome', [
  { d: 1, t: 'Compléter un tableau', fig: SVG(460, 160, `<rect x="10" y="10" width="440" height="140" fill="none" stroke="#14213d"/>${[38, 66, 94, 122].map(y => `<line x1="10" y1="${y}" x2="450" y2="${y}" stroke="#14213d"/>`).join('')}${[110, 200, 290, 370].map(x => `<line x1="${x}" y1="10" x2="${x}" y2="150" stroke="#14213d"/>`).join('')}${['entité', 'protons', 'neutrons', 'électrons', 'charge'].map((c, j) => `<text x="${[60, 155, 245, 330, 410][j]}" y="30" text-anchor="middle" font-weight="bold">${c}</text>`).join('')}${['¹⁹₉F', '²³₁₁Na⁺', '³²₁₆S²⁻', '⁴⁰₂₀Ca²⁺'].map((c, k) => `<text x="60" y="${58 + k * 28}" text-anchor="middle">${c}</text>${[155, 245, 330, 410].map(x => `<text x="${x}" y="${58 + k * 28}" text-anchor="middle">?</text>`).join('')}`).join('')}`),
    q: TX`Compléter le tableau : nombre de protons, de neutrons, d’électrons et charge (en \(e\)) de chaque entité. Lesquelles sont des ions ? des cations ? des anions ?`,
    s: TX`F : 9 p, 10 n, 9 e⁻, 0. \(\text{Na}^+\) : 11 p, 12 n, 10 e⁻, \(+e\). \(\text{S}^{2-}\) : 16 p, 16 n, 18 e⁻, \(-2e\). \(\text{Ca}^{2+}\) : 20 p, 20 n, 18 e⁻, \(+2e\).<br>Ions : \(\text{Na}^+\), \(\text{Ca}^{2+}\) (cations) et \(\text{S}^{2-}\) (anion).` },
  { d: 2, t: 'L’expérience de Rutherford', fig: SVG(440, 160, `<rect x="250" y="20" width="6" height="120" fill="#d98200"/><text x="262" y="30" font-size="11">feuille d’or</text>${[40, 60, 80, 100, 120].map(y => `<line x1="20" y1="${y}" x2="420" y2="${y}" stroke="#1f6fe0" stroke-width="1.5"/>`).join('')}<path d="M20 70 L250 70 L120 20" fill="none" stroke="#d93a4a" stroke-width="2"/><path d="M20 90 L250 90 L390 140" fill="none" stroke="#d98200" stroke-width="2"/><text x="24" y="152" font-size="11">particules α</text>`),
    q: TX`Rutherford bombarde une très fine feuille d’or avec des particules α (positives). Presque toutes la traversent sans être déviées ; quelques-unes sont fortement déviées ; de très rares rebondissent.<br>1) Que peut-on conclure du fait que presque toutes traversent ?<br>2) Pourquoi certaines sont-elles déviées ou renvoyées ?<br>3) Le rayon de l’atome d’or est d’environ \(1{,}4\times10^{-10}\ \text{m}\) et celui de son noyau \(7\times10^{-15}\ \text{m}\). Calculer le rapport. Si le noyau était une bille de 1 cm, quel serait le diamètre de l’atome ?`,
    s: TX`1) La matière est essentiellement vide : structure lacunaire.<br>2) Elles passent près d’un noyau très petit, chargé positivement et massif, qui les repousse.<br>3) \(\dfrac{1{,}4\times10^{-10}}{7\times10^{-15}} = 2\times10^{4}\) : l’atome aurait un diamètre de 200 m.` },
  { d: 2, t: 'Masse d’un atome de carbone', fig: SVG(260, 140, ball(130, 70, 50, '#5b6577', '') + `<text x="130" y="76" text-anchor="middle" fill="#fff" font-size="18" font-weight="bold">¹²C</text>`),
    q: TX`\(m_p \approx m_n = 1{,}67\times10^{-27}\ \text{kg}\) ; \(m_e = 9{,}1\times10^{-31}\ \text{kg}\).<br>1) Calculer la masse du noyau de carbone 12 et celle de ses électrons.<br>2) Montrer que la masse de l’atome est pratiquement celle du noyau.<br>3) Combien d’atomes contient un morceau de carbone pur de 1,0 g ?`,
    s: TX`1) Noyau : \(12\times1{,}67\times10^{-27} \approx 2{,}0\times10^{-26}\ \text{kg}\) ; électrons : \(6\times9{,}1\times10^{-31} \approx 5{,}5\times10^{-30}\ \text{kg}\).<br>2) Les électrons représentent environ 0,03 % de la masse : négligeable.<br>3) \(N = \dfrac{1{,}0\times10^{-3}}{2{,}0\times10^{-26}} = 5{,}0\times10^{22}\) atomes.` },
  { d: 3, t: 'Identifier un ion', fig: SVG(260, 140, ball(130, 70, 20, '#d93a4a', '') + `<circle cx="130" cy="70" r="40" fill="none" stroke="#5b6577"/><circle cx="130" cy="70" r="62" fill="none" stroke="#5b6577" stroke-dasharray="4 3"/><text x="130" y="76" text-anchor="middle" fill="#fff" font-weight="bold">?</text>`),
    q: TX`Un ion \(\text{X}^{3+}\) possède 10 électrons ; son noyau contient 14 neutrons. \(e = 1{,}6\times10^{-19}\ \text{C}\).<br>1) Déterminer le numéro atomique Z et le nombre de nucléons A.<br>2) Identifier l’élément à l’aide du tableau périodique et écrire le symbole complet de l’ion.<br>3) Calculer la charge du noyau.<br>4) Donner la structure électronique de l’atome puis celle de l’ion.`,
    s: TX`1) L’ion a perdu 3 électrons : \(Z = 10 + 3 = 13\) ; \(A = 13 + 14 = 27\).<br>2) \(Z = 13\) : aluminium, \({}^{27}_{13}\text{Al}^{3+}\).<br>3) \(q = 13\times1{,}6\times10^{-19} \approx 2{,}1\times10^{-18}\ \text{C}\).<br>4) Atome : \((\text{K})^2(\text{L})^8(\text{M})^3\) ; ion : \((\text{K})^2(\text{L})^8\).` },
]);

/* ---------- Géométrie des molécules ---------- */
const AT = (x, y, s, c) => `<circle cx="${x}" cy="${y}" r="${s === 'H' ? 11 : 17}" fill="${c}" stroke="#14213d"/><text x="${x}" y="${y + 5}" text-anchor="middle" font-weight="bold" fill="${s === 'H' ? '#14213d' : '#fff'}">${s}</text>`;
addExos('tcc-molecules', [
  { d: 1, t: 'Reconnaître la géométrie', fig: SVG(480, 150, `<line x1="80" y1="70" x2="80" y2="25" stroke="#5b6577" stroke-width="5"/><line x1="80" y1="70" x2="40" y2="100" stroke="#5b6577" stroke-width="5"/><line x1="80" y1="70" x2="120" y2="100" stroke="#5b6577" stroke-width="5"/><line x1="80" y1="70" x2="96" y2="115" stroke="#5b6577" stroke-width="5"/>${AT(80, 25, 'H', '#fff')}${AT(40, 100, 'H', '#fff')}${AT(120, 100, 'H', '#fff')}${AT(96, 115, 'H', '#fff')}${AT(80, 70, 'C', '#14213d')}<text x="80" y="145" text-anchor="middle">(a)</text>
      <line x1="240" y1="60" x2="200" y2="100" stroke="#5b6577" stroke-width="5"/><line x1="240" y1="60" x2="280" y2="100" stroke="#5b6577" stroke-width="5"/><line x1="240" y1="60" x2="240" y2="110" stroke="#5b6577" stroke-width="5"/>${AT(200, 100, 'H', '#fff')}${AT(280, 100, 'H', '#fff')}${AT(240, 110, 'H', '#fff')}${AT(240, 60, 'N', '#1f6fe0')}<text x="240" y="145" text-anchor="middle">(b)</text>
      <line x1="400" y1="60" x2="360" y2="95" stroke="#5b6577" stroke-width="5"/><line x1="400" y1="60" x2="440" y2="95" stroke="#5b6577" stroke-width="5"/>${AT(360, 95, 'H', '#fff')}${AT(440, 95, 'H', '#fff')}${AT(400, 60, 'O', '#d93a4a')}<text x="400" y="145" text-anchor="middle">(c)</text>`),
    q: TX`On a construit trois molécules avec des modèles moléculaires.<br>1) Écrire leurs formules brutes et les nommer.<br>2) Donner la géométrie de chacune.<br>3) Combien de doublets non liants porte l’atome central dans chaque cas ?`,
    s: TX`1) (a) \(\text{CH}_4\) méthane ; (b) \(\text{NH}_3\) ammoniac ; (c) \(\text{H}_2\text{O}\) eau.<br>2) (a) tétraédrique ; (b) pyramidale ; (c) coudée.<br>3) (a) 0 ; (b) 1 ; (c) 2.` },
  { d: 2, t: 'Liaisons multiples', fig: SVG(420, 110, `<text x="20" y="40" font-size="13">Méthanal : CH₂O (C central)</text><text x="20" y="80" font-size="13">Cyanure d’hydrogène : HCN (C central)</text><text x="300" y="60" font-size="12">H : 1 e⁻ ext. ; C : 4 ;</text><text x="300" y="80" font-size="12">N : 5 ; O : 6</text>`),
    q: TX`1) Calculer le nombre total de doublets dans \(\text{CH}_2\text{O}\) et dans \(\text{HCN}\).<br>2) Établir leurs schémas de Lewis (chaque atome doit respecter le duet ou l’octet).<br>3) Quelles liaisons multiples apparaissent ?`,
    s: TX`1) \(\text{CH}_2\text{O}\) : \(\dfrac{2 + 4 + 6}{2} = 6\) doublets ; \(\text{HCN}\) : \(\dfrac{1 + 4 + 5}{2} = 5\) doublets.<br>2) Méthanal : C lié à deux H et doublement lié à O, O porte 2 doublets non liants. HCN : \(\text{H–C}\equiv\text{N}\), N porte 1 doublet non liant.<br>3) Une double liaison C=O et une triple liaison C≡N.` },
  { d: 2, t: 'Isomères de C₄H₁₀', fig: SVG(420, 130, `<text x="20" y="34" font-size="16">CH₃ – CH₂ – CH₂ – CH₃</text><text x="300" y="34" font-weight="bold">(A)</text><text x="20" y="116" font-size="16">CH₃ – CH – CH₃</text><text x="76" y="70" font-size="16">CH₃</text><line x1="88" y1="76" x2="88" y2="100" stroke="#14213d" stroke-width="1.6"/><text x="300" y="116" font-weight="bold">(B)</text>`),
    q: TX`On donne deux formules semi-développées (A) et (B).<br>1) Montrer qu’elles correspondent à la même formule brute.<br>2) Que sont (A) et (B) l’une pour l’autre ?<br>3) Écrire la formule développée de (A).`,
    s: TX`1) Toutes deux contiennent 4 C et 10 H : \(\text{C}_4\text{H}_{10}\).<br>2) Des isomères (chaîne linéaire : butane ; chaîne ramifiée : méthylpropane).<br>3) Chaque C porte des liaisons simples : H₃C–CH₂–CH₂–CH₃ en détaillant les 10 liaisons C–H et les 3 liaisons C–C.` },
  { d: 3, t: 'L’ion ammonium', fig: SVG(300, 140, `<line x1="150" y1="70" x2="150" y2="22" stroke="#5b6577" stroke-width="5"/><line x1="150" y1="70" x2="104" y2="100" stroke="#5b6577" stroke-width="5"/><line x1="150" y1="70" x2="196" y2="100" stroke="#5b6577" stroke-width="5"/><line x1="150" y1="70" x2="166" y2="118" stroke="#5b6577" stroke-width="5"/>${AT(150, 22, 'H', '#fff')}${AT(104, 100, 'H', '#fff')}${AT(196, 100, 'H', '#fff')}${AT(166, 118, 'H', '#fff')}${AT(150, 70, 'N', '#1f6fe0')}<text x="210" y="40" font-size="20" font-weight="bold">+</text>`),
    q: TX`L’ion ammonium \(\text{NH}_4^+\) se forme quand une molécule d’ammoniac \(\text{NH}_3\) capte un ion \(\text{H}^+\).<br>1) Combien d’électrons externes l’ion possède-t-il au total ? En déduire le nombre de doublets.<br>2) Écrire son schéma de Lewis et préciser la position de la charge.<br>3) Prévoir sa géométrie. Comparer à celle de \(\text{CH}_4\).`,
    s: TX`1) \(5 + 4\times1 - 1 = 8\) électrons, soit 4 doublets (tous liants).<br>2) N lié à quatre H par des liaisons simples, sans doublet non liant ; la charge \(+\) est portée par N.<br>3) Quatre doublets liants : tétraédrique, comme \(\text{CH}_4\) (angles de 109,5°).` },
]);

/* ---------- Classification périodique ---------- */
const PT = (marks) => SVG(440, 190, Array.from({ length: 3 }, (_, p) => Array.from({ length: 8 }, (_, g) => (p === 0 && g > 0 && g < 7) ? '' : `<rect x="${20 + g * 52}" y="${12 + p * 56}" width="48" height="50" rx="6" fill="#eef2f8" stroke="#14213d"/>`).join('')).join('') + marks.map(([s, p, g]) => `<text x="${44 + (g - 1) * 52}" y="${44 + (p - 1) * 56}" text-anchor="middle" font-size="18" font-weight="bold" fill="#d93a4a">${s}</text>`).join(''));
addExos('tcc-classification', [
  { d: 1, t: 'Retrouver des éléments', fig: PT([['X', 2, 3], ['Y', 3, 1], ['W', 3, 7]]),
    q: TX`Les lettres X, Y et W représentent trois éléments placés dans la classification simplifiée.<br>1) Donner, pour chacun, la période, le groupe, la structure électronique et le numéro atomique.<br>2) Identifier ces éléments.<br>3) Quels ions monoatomiques donnent Y et W ?`,
    s: TX`1) X : période 2, groupe III, \((\text{K})^2(\text{L})^3\), \(Z = 5\) ; Y : période 3, groupe I, \((\text{K})^2(\text{L})^8(\text{M})^1\), \(Z = 11\) ; W : période 3, groupe VII, \((\text{K})^2(\text{L})^8(\text{M})^7\), \(Z = 17\).<br>2) X : bore ; Y : sodium ; W : chlore.<br>3) \(\text{Na}^+\) et \(\text{Cl}^-\).` },
  { d: 2, t: 'Le magnésium et ses composés', fig: PT([['Mg', 3, 2], ['O', 2, 6], ['Cl', 3, 7]]),
    q: TX`1) Donner la structure électronique du magnésium (\(Z = 12\)), son groupe et sa famille.<br>2) Quel ion forme-t-il ? Justifier par la règle de l’octet.<br>3) Écrire la formule du chlorure de magnésium et de l’oxyde de magnésium (composés électriquement neutres).`,
    s: TX`1) \((\text{K})^2(\text{L})^8(\text{M})^2\) : groupe II, alcalino-terreux.<br>2) Il perd ses 2 électrons externes pour avoir l’octet sur L : \(\text{Mg}^{2+}\).<br>3) \(\text{Mg}^{2+}\) et \(2\,\text{Cl}^-\) : \(\text{MgCl}_2\) ; \(\text{Mg}^{2+}\) et \(\text{O}^{2-}\) : \(\text{MgO}\).` },
  { d: 2, t: 'Formules de composés ioniques', fig: PT([['Na', 3, 1], ['Al', 3, 3], ['S', 3, 6], ['F', 2, 7]]),
    q: TX`À l’aide de la position des éléments, prévoir les ions formés par Na, Al, S et F, puis écrire la formule des composés neutres : fluorure de sodium, sulfure de sodium, fluorure d’aluminium, sulfure d’aluminium.`,
    s: TX`Ions : \(\text{Na}^+\), \(\text{Al}^{3+}\), \(\text{S}^{2-}\), \(\text{F}^-\).<br>\(\text{NaF}\) ; \(\text{Na}_2\text{S}\) ; \(\text{AlF}_3\) ; \(\text{Al}_2\text{S}_3\).` },
  { d: 3, t: 'Un élément mystère', fig: PT([['?', 3, 6]]),
    q: TX`Un élément X forme un ion \(\text{X}^{2-}\) qui a la même structure électronique que l’argon (\(Z = 18\)).<br>1) Déterminer le numéro atomique de X et l’identifier.<br>2) Préciser sa période et son groupe ; citer un autre élément de la même famille.<br>3) Combien de liaisons covalentes X forme-t-il ? Écrire le schéma de Lewis de \(\text{H}_2\text{X}\) et prévoir sa géométrie.`,
    s: TX`1) L’ion a 18 électrons et 2 de plus que l’atome : \(Z = 16\), soufre S.<br>2) Période 3, groupe VI ; l’oxygène est dans la même famille.<br>3) \(8 - 6 = 2\) liaisons : \(\text{H–S–H}\) avec deux doublets non liants sur S ; molécule coudée (comme \(\text{H}_2\text{O}\)).` },
]);

/* ---------- La mole ---------- */
addExos('tcc-mole', [
  { d: 1, t: 'Calculer des masses molaires', fig: SVG(420, 80, `<text x="20" y="34" font-size="13">H = 1 ; C = 12 ; O = 16 ; S = 32 ; Ca = 40 (g/mol)</text><text x="20" y="64" font-size="15">C₆H₁₂O₆ ; H₂SO₄ ; Ca(OH)₂ ; CO₂</text>`),
    q: TX`Calculer la masse molaire du glucose \(\text{C}_6\text{H}_{12}\text{O}_6\), de l’acide sulfurique \(\text{H}_2\text{SO}_4\), de l’hydroxyde de calcium \(\text{Ca(OH)}_2\) et du dioxyde de carbone. En déduire la quantité de matière contenue dans 9,0 g de glucose.`,
    s: TX`\(M(\text{C}_6\text{H}_{12}\text{O}_6) = 6\times12 + 12 + 6\times16 = 180\ \text{g/mol}\) ; \(M(\text{H}_2\text{SO}_4) = 98\ \text{g/mol}\) ; \(M(\text{Ca(OH)}_2) = 40 + 2\times17 = 74\ \text{g/mol}\) ; \(M(\text{CO}_2) = 44\ \text{g/mol}\).<br>\(n = \dfrac{9{,}0}{180} = 0{,}050\ \text{mol}\).` },
  { d: 2, t: 'Prélever un liquide', fig: SVG(220, 200, `<rect x="80" y="10" width="50" height="180" rx="6" fill="#fff" stroke="#14213d" stroke-width="2"/><rect x="82" y="110" width="46" height="78" fill="#eaf1fd"/>${[0, 1, 2, 3, 4, 5, 6, 7, 8].map(k => `<line x1="80" y1="${30 + k * 20}" x2="92" y2="${30 + k * 20}" stroke="#14213d"/>`).join('')}<text x="140" y="114" font-size="11">éthanol</text>`),
    q: TX`On mesure 10,0 mL d’éthanol \(\text{C}_2\text{H}_6\text{O}\) (\(\rho = 0{,}79\ \text{g/mL}\)) avec une éprouvette.<br>1) Calculer la masse molaire de l’éthanol.<br>2) Calculer la masse puis la quantité de matière prélevée.<br>3) Combien de molécules contient l’échantillon ?`,
    s: TX`1) \(M = 2\times12 + 6 + 16 = 46\ \text{g/mol}\).<br>2) \(m = \rho V = 7{,}9\ \text{g}\) ; \(n = \dfrac{7{,}9}{46} \approx 0{,}17\ \text{mol}\).<br>3) \(N = nN_A \approx 0{,}17\times6{,}02\times10^{23} \approx 1{,}0\times10^{23}\).` },
  { d: 2, t: 'Le ballon d’hélium', fig: SVG(200, 200, `<ellipse cx="100" cy="70" rx="55" ry="62" fill="#ff9b45" stroke="#14213d"/><path d="M100 132 q-10 30 5 60" fill="none" stroke="#5b6577"/><text x="100" y="76" text-anchor="middle" fill="#fff" font-weight="bold">He</text>`),
    q: TX`Un ballon contient 5,0 L d’hélium (\(M = 4{,}0\ \text{g/mol}\)) à 20 °C, où \(V_m = 24\ \text{L/mol}\).<br>1) Calculer la quantité de matière et la masse d’hélium.<br>2) Calculer la densité de l’hélium par rapport à l’air. Expliquer pourquoi le ballon monte.<br>3) Quel volume occuperait la même quantité de dioxyde de carbone ?`,
    s: TX`1) \(n = \dfrac{5{,}0}{24} \approx 0{,}21\ \text{mol}\) ; \(m = 0{,}21\times4{,}0 \approx 0{,}83\ \text{g}\).<br>2) \(d = \dfrac{4}{29} \approx 0{,}14 < 1\) : l’hélium est beaucoup plus léger que l’air.<br>3) Même volume, 5,0 L (loi d’Avogadro-Ampère).` },
  { d: 3, t: 'Qui contient le plus de molécules ?', fig: SVG(440, 130, `${[['1,0 g de H₂', 70, '#eaf1fd'], ['10 g de H₂O', 220, '#6aa5ff'], ['11,2 L de CO₂', 370, '#e3e9f3']].map(([t, x, c]) => `<rect x="${x - 45}" y="20" width="90" height="80" rx="10" fill="${c}" stroke="#14213d"/><text x="${x}" y="120" text-anchor="middle" font-size="12">${t}</text>`).join('')}`),
    q: TX`On dispose de trois échantillons : 1,0 g de dihydrogène, 10 g d’eau liquide et 11,2 L de dioxyde de carbone mesurés dans des conditions où \(V_m = 22{,}4\ \text{L/mol}\).<br>1) Calculer la quantité de matière de chacun.<br>2) Classer les échantillons selon le nombre de molécules.<br>3) Calculer la masse du dioxyde de carbone. Le plus lourd est-il celui qui contient le plus de molécules ?`,
    s: TX`1) \(\text{H}_2\) : \(\dfrac{1{,}0}{2} = 0{,}50\ \text{mol}\) ; \(\text{H}_2\text{O}\) : \(\dfrac{10}{18} \approx 0{,}56\ \text{mol}\) ; \(\text{CO}_2\) : \(\dfrac{11{,}2}{22{,}4} = 0{,}50\ \text{mol}\).<br>2) L’eau contient le plus de molécules ; \(\text{H}_2\) et \(\text{CO}_2\) autant l’un que l’autre.<br>3) \(m = 0{,}50\times44 = 22\ \text{g}\) : c’est le plus lourd mais pas le plus nombreux en molécules.` },
]);

/* ---------- La concentration molaire ---------- */
addExos('tcc-concentration', [
  { d: 1, t: 'Le sérum physiologique', fig: SVG(220, 200, `<rect x="70" y="40" width="80" height="140" rx="12" fill="#eaf1fd" stroke="#14213d" stroke-width="2"/><rect x="95" y="20" width="30" height="22" fill="#d93a4a"/><text x="110" y="100" text-anchor="middle" font-size="11">NaCl</text><text x="110" y="118" text-anchor="middle" font-size="11">9 g/L</text>`),
    q: TX`Le sérum physiologique est une solution de chlorure de sodium de concentration massique \(C_m = 9{,}0\ \text{g/L}\) (\(M(\text{NaCl}) = 58{,}5\ \text{g/mol}\)).<br>1) Calculer sa concentration molaire.<br>2) Quelle masse de sel faut-il pour préparer 250 mL de cette solution ?<br>3) Décrire la préparation.`,
    s: TX`1) \(C = \dfrac{C_m}{M} = \dfrac{9{,}0}{58{,}5} \approx 0{,}15\ \text{mol/L}\).<br>2) \(m = C_m V = 9{,}0\times0{,}250 = 2{,}25\ \text{g}\).<br>3) Peser 2,25 g, les introduire dans une fiole jaugée de 250 mL, dissoudre dans de l’eau distillée, compléter jusqu’au trait de jauge et homogénéiser.` },
  { d: 2, t: 'Choisir la verrerie pour diluer', fig: SVG(440, 150, `<rect x="20" y="40" width="50" height="80" fill="#eaf1fd" stroke="#14213d"/><text x="45" y="140" text-anchor="middle" font-size="11">bécher</text><rect x="110" y="20" width="22" height="100" fill="#fff" stroke="#14213d"/><text x="121" y="140" text-anchor="middle" font-size="11">éprouvette</text><line x1="200" y1="10" x2="200" y2="120" stroke="#14213d" stroke-width="3"/><ellipse cx="200" cy="65" rx="8" ry="16" fill="#fff" stroke="#14213d"/><text x="200" y="140" text-anchor="middle" font-size="11">pipette jaugée</text><circle cx="300" cy="100" r="22" fill="#fff" stroke="#14213d"/><rect x="293" y="30" width="14" height="50" fill="#fff" stroke="#14213d"/><text x="300" y="140" text-anchor="middle" font-size="11">fiole jaugée</text><path d="M380 40 h40 l-12 50 v30 h-16 v-30 z" fill="#fff" stroke="#14213d"/><text x="400" y="140" text-anchor="middle" font-size="11">erlenmeyer</text>`),
    q: TX`On veut préparer 100 mL d’une solution de concentration \(C_f = 0{,}050\ \text{mol/L}\) à partir d’une solution mère à \(C_0 = 0{,}50\ \text{mol/L}\).<br>1) Calculer le facteur de dilution et le volume \(V_0\) à prélever.<br>2) Choisir la verrerie la plus adaptée parmi celle représentée.<br>3) Rédiger le protocole.`,
    s: TX`1) \(F = \dfrac{0{,}50}{0{,}050} = 10\) ; \(V_0 = \dfrac{100}{10} = 10\ \text{mL}\).<br>2) Une pipette jaugée de 10 mL et une fiole jaugée de 100 mL (le bécher sert à contenir la solution mère).<br>3) Verser un peu de solution mère dans un bécher, prélever 10,0 mL à la pipette jaugée, les verser dans la fiole, compléter avec de l’eau distillée jusqu’au trait de jauge, boucher et agiter.` },
  { d: 2, t: 'Échelle de teintes', fig: SVG(460, 150, `${[0.02, 0.04, 0.06, 0.08, 0.10].map((c, k) => TUBE(50 + k * 80, String(c).replace('.', ','), `rgba(31,111,224,${c * 8})`, 70)).join('')}`),
    q: TX`On prépare une échelle de teintes de sulfate de cuivre aux concentrations indiquées (mol/L) sous chaque tube, dans des fioles de 50,0 mL à partir d’une solution mère à 0,20 mol/L. Un échantillon inconnu a une teinte comprise entre celles des tubes à 0,04 et 0,06 mol/L.<br>1) Quel volume de solution mère faut-il prélever pour le tube à 0,04 mol/L ?<br>2) Encadrer la concentration de l’échantillon.<br>3) Comment améliorer la précision ?`,
    s: TX`1) \(V_0 = \dfrac{C_fV_f}{C_0} = \dfrac{0{,}04\times50{,}0}{0{,}20} = 10{,}0\ \text{mL}\).<br>2) \(0{,}04\ \text{mol/L} < C < 0{,}06\ \text{mol/L}\).<br>3) Préparer des tubes intermédiaires (0,045 ; 0,050 ; 0,055 mol/L) ou utiliser un spectrophotomètre.` },
  { d: 3, t: 'Mélanger deux solutions', fig: SVG(380, 150, `<rect x="30" y="40" width="80" height="90" fill="#6aa5ff" opacity=".35" stroke="#14213d"/><text x="70" y="146" text-anchor="middle" font-size="11">100 mL ; 0,20 mol/L</text><text x="140" y="90" font-size="22">+</text><rect x="170" y="70" width="60" height="60" fill="#1f6fe0" opacity=".5" stroke="#14213d"/><text x="200" y="146" text-anchor="middle" font-size="11">50 mL ; 0,50 mol/L</text><text x="248" y="90" font-size="22">→</text><rect x="280" y="30" width="80" height="100" fill="#1f6fe0" opacity=".42" stroke="#14213d"/><text x="320" y="146" text-anchor="middle" font-size="11">C = ?</text>`),
    q: TX`On mélange 100 mL d’une solution de chlorure de sodium à 0,20 mol/L et 50 mL d’une solution de chlorure de sodium à 0,50 mol/L (\(M = 58{,}5\ \text{g/mol}\)).<br>1) Calculer la quantité de soluté apportée par chaque solution.<br>2) Calculer la concentration molaire du mélange (les volumes s’ajoutent).<br>3) En déduire sa concentration massique.<br>4) Quel volume d’eau faudrait-il ajouter au mélange pour obtenir 0,10 mol/L ?`,
    s: TX`1) \(n_1 = 0{,}20\times0{,}100 = 0{,}020\ \text{mol}\) ; \(n_2 = 0{,}50\times0{,}050 = 0{,}025\ \text{mol}\).<br>2) \(C = \dfrac{0{,}045}{0{,}150} = 0{,}30\ \text{mol/L}\).<br>3) \(C_m = 0{,}30\times58{,}5 \approx 17{,}6\ \text{g/L}\).<br>4) \(V_f = \dfrac{0{,}045}{0{,}10} = 0{,}450\ \text{L}\) : ajouter 300 mL d’eau.` },
]);

/* ---------- Transformation chimique – Bilan de matière ---------- */
addExos('tcc-transformation', [
  { d: 1, t: 'Équilibrer des équations', fig: SVG(420, 130, `<text x="20" y="30" font-size="15">a) … C₃H₈ + … O₂ → … CO₂ + … H₂O</text><text x="20" y="62" font-size="15">b) … Fe + … O₂ → … Fe₂O₃</text><text x="20" y="94" font-size="15">c) … Cu²⁺ + … Al → … Cu + … Al³⁺</text><text x="20" y="122" font-size="15">d) … N₂ + … H₂ → … NH₃</text>`),
    q: TX`Équilibrer les équations ci-contre. Pour la c), vérifier aussi la conservation des charges.`,
    s: TX`a) \(\text{C}_3\text{H}_8 + 5\,\text{O}_2 \to 3\,\text{CO}_2 + 4\,\text{H}_2\text{O}\).<br>b) \(4\,\text{Fe} + 3\,\text{O}_2 \to 2\,\text{Fe}_2\text{O}_3\).<br>c) \(3\,\text{Cu}^{2+} + 2\,\text{Al} \to 3\,\text{Cu} + 2\,\text{Al}^{3+}\) (charges : \(+6\) de chaque côté).<br>d) \(\text{N}_2 + 3\,\text{H}_2 \to 2\,\text{NH}_3\).` },
  { d: 2, t: 'Combustion du propane', fig: SVG(240, 180, `<rect x="90" y="110" width="60" height="60" rx="8" fill="#5b6577"/><path d="M120 108 C 95 80, 110 50, 120 20 C 130 50, 145 80, 120 108 Z" fill="#ffb23e" stroke="#d93a4a"/><text x="160" y="150" font-size="11">propane C₃H₈</text>`),
    q: TX`On brûle 0,10 mol de propane avec 0,40 mol de dioxygène : \(\text{C}_3\text{H}_8 + 5\,\text{O}_2 \to 3\,\text{CO}_2 + 4\,\text{H}_2\text{O}\).<br>1) Dresser le tableau d’avancement.<br>2) Déterminer le réactif limitant et l’avancement maximal.<br>3) Donner la composition du système à l’état final.<br>4) Quel volume de \(\text{CO}_2\) est produit (\(V_m = 24\ \text{L/mol}\)) ?`,
    s: TX`1) \(n(\text{C}_3\text{H}_8) = 0{,}10 - x\) ; \(n(\text{O}_2) = 0{,}40 - 5x\) ; \(n(\text{CO}_2) = 3x\) ; \(n(\text{H}_2\text{O}) = 4x\).<br>2) \(0{,}10 - x = 0 \Rightarrow x = 0{,}10\) ; \(0{,}40 - 5x = 0 \Rightarrow x = 0{,}080\) : \(\text{O}_2\) limitant, \(x_{max} = 0{,}080\ \text{mol}\).<br>3) Propane : 0,020 mol ; \(\text{O}_2\) : 0 ; \(\text{CO}_2\) : 0,24 mol ; \(\text{H}_2\text{O}\) : 0,32 mol.<br>4) \(V = 0{,}24\times24 \approx 5{,}8\ \text{L}\).` },
  { d: 2, t: 'Lecture graphique de l’avancement', fig: cfig({ w: 420, h: 230, x1: 0.3, xs: 0.05, y1: 0.4, ys: 0.1, xl: 'x (mol)', yl: 'n (mol)', f: x => Math.max(0, 0.3 - x), fmtx: x => String(x).replace('.', ','), fmty: y => String(y).replace('.', ','),
      ext: (X, Y) => `<line x1="${X(0)}" y1="${Y(0.4)}" x2="${X(0.2)}" y2="${Y(0)}" stroke="#d93a4a" stroke-width="2.6"/><text x="${X(0.03)}" y="${Y(0.33)}" fill="#d93a4a" font-weight="bold">B</text><text x="${X(0.03)}" y="${Y(0.22)}" fill="#1f6fe0" font-weight="bold">A</text>` }),
    q: TX`Pour la réaction \(\text{A} + 2\,\text{B} \to \text{C}\), on a tracé les quantités de A et de B en fonction de l’avancement \(x\).<br>1) Lire les quantités initiales de A et de B.<br>2) Écrire \(n(\text{A})\) et \(n(\text{B})\) en fonction de \(x\) et vérifier les pentes.<br>3) Déterminer le réactif limitant et \(x_{max}\).<br>4) Donner la composition finale.`,
    s: TX`1) \(n_0(\text{A}) = 0{,}30\ \text{mol}\) ; \(n_0(\text{B}) = 0{,}40\ \text{mol}\).<br>2) \(n(\text{A}) = 0{,}30 - x\) (pente \(-1\)) ; \(n(\text{B}) = 0{,}40 - 2x\) (pente \(-2\)).<br>3) B s’annule le premier, pour \(x = 0{,}20\ \text{mol}\) : B limitant, \(x_{max} = 0{,}20\ \text{mol}\).<br>4) A : 0,10 mol ; B : 0 ; C : 0,20 mol.` },
  { d: 3, t: 'Zinc et acide chlorhydrique', fig: SVG(440, 180, `<path d="M40 60 h70 v100 h-70 z" fill="#6aa5ff" opacity=".35" stroke="#14213d" stroke-width="2"/><circle cx="62" cy="145" r="6" fill="#9aa6bf"/><circle cx="82" cy="150" r="5" fill="#9aa6bf"/><path d="M75 60 V30 H300 V100" fill="none" stroke="#14213d" stroke-width="2"/><rect x="250" y="100" width="150" height="70" fill="#6aa5ff" opacity=".3" stroke="#14213d"/><rect x="285" y="60" width="30" height="90" fill="#fff" stroke="#14213d"/><text x="330" y="80" font-size="11">H₂ recueilli</text><text x="40" y="176" font-size="11">zinc + acide</text>`),
    q: TX`On fait réagir 0,65 g de zinc (\(M = 65\ \text{g/mol}\)) avec 50 mL d’acide chlorhydrique à 0,30 mol/L : \(\text{Zn} + 2\,\text{H}^+ \to \text{Zn}^{2+} + \text{H}_2\).<br>1) Calculer les quantités initiales de zinc et d’ions \(\text{H}^+\).<br>2) Déterminer le réactif limitant et \(x_{max}\).<br>3) Calculer le volume de dihydrogène recueilli (\(V_m = 24\ \text{L/mol}\)).<br>4) Quelle masse de zinc reste-t-il ? Quelle quantité d’acide faudrait-il pour tout consommer ?`,
    s: TX`1) \(n(\text{Zn}) = \dfrac{0{,}65}{65} = 0{,}010\ \text{mol}\) ; \(n(\text{H}^+) = 0{,}30\times0{,}050 = 0{,}015\ \text{mol}\).<br>2) Zn : \(x = 0{,}010\) ; \(\text{H}^+\) : \(x = \dfrac{0{,}015}{2} = 0{,}0075\) : l’acide est limitant, \(x_{max} = 7{,}5\times10^{-3}\ \text{mol}\).<br>3) \(V = 7{,}5\times10^{-3}\times24 = 0{,}18\ \text{L}\).<br>4) Reste \(0{,}010 - 0{,}0075 = 2{,}5\times10^{-3}\ \text{mol}\), soit 0,16 g. Il faudrait \(0{,}020\ \text{mol}\) d’ions \(\text{H}^+\) (66,7 mL d’acide).` },
]);
